  mode = 'driving', // 'driving' | 'walking'
  onRouteChange = null,
}) {
  const [liveOrigin, setLiveOrigin] = useState(() => origin || { lat: 14.6349, lng: -90.5069 });
  const [liveDestination, setLiveDestination] = useState(() => destination || { lat: 14.595, lng: -90.485 });
  const [customOriginName, setCustomOriginName] = useState('');
  const [customDestName, setCustomDestName] = useState('');
  const [availableRoutes, setAvailableRoutes] = useState([]);
  const [selectedRouteIndex, setSelectedRouteIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isNavigating, setIsNavigating] = useState(false);
  const simulating = isNavigating;
  const setSimulating = setIsNavigating;
  const [smoothVehiclePos, setSmoothVehiclePos] = useState([liveOrigin?.lat ?? 14.6349, liveOrigin?.lng ?? -90.5069]);
  const [currentBearing, setCurrentBearing] = useState(0);
  const [hasReachedDestination, setHasReachedDestination] = useState(false);
  const [simIndex, setSimIndex] = useState(0);
  const [simSpeed, setSimSpeed] = useState(1);
  const [followVehicle, setFollowVehicle] = useState(false);
  const currentVehiclePosRef = useRef([liveOrigin?.lat ?? 14.6349, liveOrigin?.lng ?? -90.5069]);
  const targetVehiclePosRef = useRef([liveOrigin?.lat ?? 14.6349, liveOrigin?.lng ?? -90.5069]);
  const lastRerouteTimeRef = useRef(0);
  const lastReroutePosRef = useRef(null);
  const isNavigatingRef = useRef(false);
  const silentRerouteRef = useRef(null);

  useEffect(() => {
    isNavigatingRef.current = isNavigating;
  }, [isNavigating]);

  const [mapTheme, setMapTheme] = useState('calles'); // 'calles' | 'relieve' | 'satelite'
  const [showStepDrawer, setShowStepDrawer] = useState(false);
  const [selectedStepIndex, setSelectedStepIndex] = useState(null);
  const [targetFocus, setTargetFocus] = useState(null);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [gpsLoading, setGpsLoading] = useState(false);
  const [isTracking, setIsTracking] = useState(false);
  const [gpsAccuracy, setGpsAccuracy] = useState(null);
  const [showSearchPanel, setShowSearchPanel] = useState(false);
  const [trafficRefreshTick, setTrafficRefreshTick] = useState(0);

  // Voice Assistant Settings
  const [voiceEnabled, setVoiceEnabled] = useState(true);
  const [voiceDialect, setVoiceDialect] = useState('dalia'); // 'dalia' | 'latino' | 'espana' | 'auto'
  const [availableVoices, setAvailableVoices] = useState([]);
  const [showVoiceMenu, setShowVoiceMenu] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [lastSpokenText, setLastSpokenText] = useState('');
  const [showSubtitle, setShowSubtitle] = useState(false);
  const subtitleTimeoutRef = useRef(null);
  const lastSpokenStepRef = useRef(-1);

  const mapInstanceRef = useRef(null);
  const containerRef = useRef(null);
  const animRef = useRef(null);
  const gpsWatchRef = useRef(null);
  const bestGpsAccuracyRef = useRef(Infinity);
  const lastGpsPositionRef = useRef(null);
  const lastGpsUpdateRef = useRef(0);
  const lastRouteAlertRef = useRef('');

  const originLat = liveOrigin?.lat ?? 14.6349;
  const originLng = liveOrigin?.lng ?? -90.5069;
  const destLat = liveDestination?.lat ?? 14.595;
  const destLng = liveDestination?.lng ?? -90.485;

  // Refresh live traffic estimates without requiring the user to reload.
  useEffect(() => {
    if (!MAPBOX_ACCESS_TOKEN || mode !== 'driving') return undefined;
    const timer = setInterval(() => setTrafficRefreshTick((tick) => tick + 1), 120000);
    return () => clearInterval(timer);
  }, [mode]);

  const displayDestName = customDestName || propertyAddress;

  // Sync origin prop with liveOrigin when GPS is not actively overriding
  useEffect(() => {
    if (origin?.lat && origin?.lng && !isTracking) {
      setLiveOrigin(origin);
    }
  }, [origin?.lat, origin?.lng, isTracking]);

  // Update destination when prop changes
  useEffect(() => {
    if (destination?.lat && destination?.lng) {
      setLiveDestination(destination);
    }
  }, [destination]);

  // Load and cache Spanish voices asynchronously
  useEffect(() => {
    if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
      const loadVoices = () => {
        const vList = window.speechSynthesis.getVoices() || [];
        if (vList.length > 0) {
          setAvailableVoices(vList);
        }
      };
      loadVoices();
      window.speechSynthesis.onvoiceschanged = loadVoices;

      // Some browsers delay populating getVoices(); check briefly
      const pollTimer = setInterval(() => {
        const vList = window.speechSynthesis.getVoices() || [];
        if (vList.length > 0) {
          setAvailableVoices(vList);
          clearInterval(pollTimer);
        }
      }, 150);

      return () => {
        clearInterval(pollTimer);
        if (window.speechSynthesis) window.speechSynthesis.onvoiceschanged = null;
      };
    }
  }, []);

  // Locate the real Microsoft Dalia voice exposed by the browser.
  const findDaliaVoice = useCallback(() => {
    if (typeof window === 'undefined' || !('speechSynthesis' in window)) return null;
    const browserVoices = window.speechSynthesis.getVoices() || [];
    const all = browserVoices.length > 0 ? browserVoices : availableVoices;

    return all.find((voice) => {
      const name = voice.name?.toLowerCase() || '';
      const lang = voice.lang?.toLowerCase().replace('_', '-') || '';
      return name.includes('dalia') && (lang === 'es-mx' || /spanish.*mexico|mexico.*spanish/.test(name));
    }) || null;
  }, [availableVoices]);

  // Fallback: find the best available Spanish voice (Dalia > es-MX > es-*)
  const findBestSpanishVoice = useCallback(() => {
    // 1. Try Dalia first
    const dalia = findDaliaVoice();
    if (dalia) return dalia;

    // 2. Gather all voices
    if (typeof window === 'undefined' || !('speechSynthesis' in window)) return null;
    const browserVoices = window.speechSynthesis.getVoices() || [];
    const all = browserVoices.length > 0 ? browserVoices : availableVoices;

    // 3. Try es-MX voices (Mexican Spanish)
    const esMX = all.find((v) => {
      const lang = v.lang?.toLowerCase().replace('_', '-') || '';
      return lang === 'es-mx';
    });
    if (esMX) return esMX;

    // 4. Try any es-* Spanish voice
    const esAny = all.find((v) => {
      const lang = v.lang?.toLowerCase().replace('_', '-') || '';
      return lang.startsWith('es');
    });
    if (esAny) return esAny;

    return null;
  }, [findDaliaVoice, availableVoices]);

  const detectedDaliaVoice = useMemo(() => findDaliaVoice(), [findDaliaVoice, availableVoices]);
  const activeSpanishVoice = useMemo(() => findBestSpanishVoice(), [findBestSpanishVoice, availableVoices]);

  // Voice Assistant: uses Dalia when available, falls back to any Spanish voice
  const speakAssistant = useCallback((text) => {
    if (!voiceEnabled || typeof window === 'undefined' || !('speechSynthesis' in window)) return;
    if (!text) return;

    // Always display the true navigation instruction in the subtitle banner immediately
    setLastSpokenText(text);
    setShowSubtitle(true);
    if (subtitleTimeoutRef.current) clearTimeout(subtitleTimeoutRef.current);
    subtitleTimeoutRef.current = setTimeout(() => setShowSubtitle(false), 6500);

    const performSpeech = () => {
      try {
        if (window.speechSynthesis.paused) {
          window.speechSynthesis.resume();
        }
        window.speechSynthesis.cancel();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'es-MX'; // Mexican Spanish preferred

        // Try Dalia first, then any Spanish voice
        const voice = findBestSpanishVoice();
        if (!voice) {
          // No Spanish voice at all – still show text but don't block
          setIsSpeaking(false);
          setLastSpokenText(text);
          setShowSubtitle(true);
          console.warn('No se encontró ninguna voz en español en el navegador.');
          return;
        }

        utterance.voice = voice;
        utterance.lang = voice.lang || 'es-MX';

        // Natural cadence
        utterance.rate = 1.0;
        utterance.pitch = 1.0;
        utterance.volume = 1.0;

        utterance.onstart = () => setIsSpeaking(true);
        utterance.onend = () => setIsSpeaking(false);
        utterance.onerror = () => setIsSpeaking(false);

        // Small tick to prevent Chromium cancellation bug
        setTimeout(() => {
          try {
            window.speechSynthesis.speak(utterance);
          } catch (e) {
            console.warn('Speech error:', e);
          }
        }, 35);
      } catch (err) {
        console.warn('Error en asistente de voz:', err);
      }
    };

    const currentList = window.speechSynthesis.getVoices() || [];
    if (currentList.length > 0) {
      performSpeech();
    } else {
      window.speechSynthesis.addEventListener('voiceschanged', performSpeech, { once: true });
      setTimeout(performSpeech, 120);
    }
  }, [voiceEnabled, findBestSpanishVoice]);

  // 1. Fetch real street route from multi-provider OSRM (with alternatives & shortest route sorting)
  useEffect(() => {
    let isMounted = true;
    if (isNavigating) return;
    setLoading(true);
    // Do not keep showing metrics that belong to the previous origin.
    setAvailableRoutes([]);
    setSelectedRouteIndex(0);

    const fetchOptimalRoutes = async () => {
      const routerProfile = mode === 'walking' ? 'foot' : 'car';
      const osrmProfile = mode === 'walking' ? 'walking' : 'driving';
      const endpoints = [];
      if (MAPBOX_ACCESS_TOKEN) {
        const mapboxProfile = mode === 'walking' ? 'mapbox/walking' : 'mapbox/driving-traffic';
        endpoints.push({
          provider: mode === 'driving' ? 'mapbox-traffic' : 'mapbox',
          url: `https://api.mapbox.com/directions/v5/${mapboxProfile}/${originLng},${originLat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true&alternatives=true&language=es&annotations=duration,distance${mode === 'driving' ? ',congestion,congestion_numeric,closure' : ''}&access_token=${encodeURIComponent(MAPBOX_ACCESS_TOKEN)}`,
        });
      }
      endpoints.push(
        ...(mode === 'driving' ? [{ provider: 'osrm', url: `https://router.project-osrm.org/route/v1/driving/${originLng},${originLat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true&alternatives=true` }] : []),
        { provider: 'osrm', url: `https://routing.openstreetmap.de/routed-${routerProfile}/route/v1/${osrmProfile}/${originLng},${originLat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true&alternatives=true` },
      );

      for (const endpoint of endpoints) {
        try {
          const res = await fetch(endpoint.url, { signal: AbortSignal.timeout(15000) });
          if (!res.ok) continue;
          const data = await res.json();

          if (isMounted && data.routes && data.routes.length > 0) {
            // Sort all real street routes by shortest distance in meters
            const parsedRoutes = data.routes
              .map((r, i) => {
                const rawCoords = r.geometry.coordinates.map(([lng, lat]) => [lat, lng]);
                const legSteps = r.legs?.[0]?.steps || [];
                const leg = r.legs?.[0];
                const summary = leg?.summary || (i === 0 ? 'Vía principal recomendada' : 'Vía alternativa');
                const incidents = leg?.incidents || [];
                const closures = leg?.closures || [];
                const congestionValues = (leg?.annotation?.congestion_numeric || []).filter(Number.isFinite);
                const averageCongestion = congestionValues.length
                  ? Math.round(congestionValues.reduce((sum, value) => sum + value, 0) / congestionValues.length)
                  : null;

                const maneuvers = legSteps.map((step, idx) => {
                  const mType = step.maneuver?.type;
                  const modifier = step.maneuver?.modifier;
                  const streetName = step.name ? step.name.trim() : '';

                  let icon = 'straight';
                  if (modifier?.includes('left')) icon = 'left';
                  else if (modifier?.includes('right')) icon = 'right';
                  else if (mType === 'roundabout') icon = 'roundabout';
                  else if (idx === legSteps.length - 1) icon = 'destination';

                  let instruction = '';
                  if (idx === legSteps.length - 1) {
                    instruction = `Llegada a tu destino: ${streetName || displayDestName}`;
                  } else if (idx === 0) {
                    instruction = streetName ? `Inicia tu recorrido por ${streetName}` : 'Inicia tu recorrido hacia la vía principal';
                  } else if (mType === 'turn' || mType === 'fork') {
                    const dir = modifier === 'left' ? 'la izquierda' : modifier === 'right' ? 'la derecha' : 'adelante';
                    instruction = streetName ? `Gira a ${dir} en ${streetName}` : `Gira a ${dir}`;
                  } else if (mType === 'roundabout') {
                    instruction = streetName ? `En la rotonda, toma la salida hacia ${streetName}` : 'En la rotonda, toma la salida señalada';
                  } else {
                    instruction = streetName ? `Avanza por ${streetName}` : 'Continúa recto por la calzada';
                  }

                  return {
                    instruction,
                    streetName: streetName || 'Vía conectora',
                    distance: step.distance,
                    duration: step.duration,
                    location: [step.maneuver?.location?.[1] || rawCoords[0][0], step.maneuver?.location?.[0] || rawCoords[0][1]],
                    icon,
                  };
                });

                const realWorld = calculateRealWorldFactors({
                  distanceMeters: r.distance,
                  baseDurationSeconds: r.duration,
                  mode,
                  maneuvers,
                  incidents,
                  closures,
                });

                return {
                  id: `route-${i}`,
                  title: i === 0 ? 'Ruta más corta (Calles reales)' : `Ruta alternativa ${i}`,
                  summary,
                  coords: rawCoords,
                  distanceMeters: r.distance,
                  durationSeconds: realWorld.totalAdjustedSeconds,
                  baseDurationSeconds: r.duration,
                  typicalDurationSeconds: r.duration_typical || null,
                  trafficDelaySeconds: realWorld.trafficDelayMins * 60,
                  trafficAware: true,
                  realWorld,
                  incidents,
                  closures,
                  averageCongestion,
                  updatedAt: new Date().toISOString(),
                  steps: maneuvers,
                };
              })
              .sort((a, b) => {
                const closureA = (a.closures?.length || 0) * 100000;
                const closureB = (b.closures?.length || 0) * 100000;
                // Garantizar la ruta más corta en la calle real
                return (a.distanceMeters + closureA) - (b.distanceMeters + closureB);
              });

            // Set shortest route as primary
            setAvailableRoutes(parsedRoutes);
            setSelectedRouteIndex(0);
            return;
          }
        } catch (err) {
          console.warn('Endpoint error, intentando respaldo...', err);
        }
      }
    };

    fetchOptimalRoutes().finally(() => {
      if (isMounted) setLoading(false);
    });

    return () => {
      isMounted = false;
    };
  }, [originLat, originLng, destLat, destLng, mode, displayDestName, trafficRefreshTick, isNavigating]);

  // Current active route data (defaults to the shortest road path)
  const currentRoute = availableRoutes[selectedRouteIndex] || availableRoutes[0] || null;
  const routeCoordinates = currentRoute?.coords || [];
  const steps = currentRoute?.steps || [];
  const totalDistanceMeters = currentRoute?.distanceMeters || 0;
  const totalDurationSeconds = currentRoute?.durationSeconds || 0;
  const routeSummary = currentRoute?.summary || 'Calles principales de la ciudad';

  // Alternative route (for map overlay)
  const alternativeRoute = availableRoutes.length > 1 ? availableRoutes[selectedRouteIndex === 0 ? 1 : 0] : null;

  // Notify parent component of current route metrics
  useEffect(() => {
    if (currentRoute && typeof onRouteChange === 'function') {
      const adjustedMins = currentRoute.realWorld?.totalAdjustedMins || Math.max(3, Math.round(totalDurationSeconds / 60));
      onRouteChange({
        origin: liveOrigin,
        originName: customOriginName || (isTracking ? 'Tu Ubicación GPS en Vivo' : 'Tu Ubicación'),
        destination: liveDestination,
        customDestName: customDestName || propertyTitle,
        customDestAddress: customDestName || propertyAddress,
        distanceKm: (totalDistanceMeters / 1000).toFixed(1),
        durationMins: adjustedMins,
        baseDurationMins: currentRoute.realWorld?.baseDurationMins || Math.max(2, Math.round((currentRoute.baseDurationSeconds || totalDurationSeconds) / 60)),
        realWorld: currentRoute.realWorld,
        routeSummary,
        trafficAware: currentRoute.trafficAware,
        trafficDelayMins: currentRoute.realWorld?.trafficDelayMins || Math.round((currentRoute.trafficDelaySeconds || 0) / 60),
        incidents: currentRoute.incidents || [],
        closures: currentRoute.closures || [],
        updatedAt: currentRoute.updatedAt,
      });
    }
  }, [currentRoute, totalDistanceMeters, totalDurationSeconds, routeSummary, liveOrigin, liveDestination, customDestName, customOriginName, propertyTitle, propertyAddress, isTracking, onRouteChange]);

  // Welcome speech greeting on initial route calculation
  useEffect(() => {
    if (totalDistanceMeters > 0) {
      const distKm = (totalDistanceMeters / 1000).toFixed(1);
      const mins = currentRoute?.realWorld?.totalAdjustedMins || Math.max(3, Math.round(totalDurationSeconds / 60));
      const firstStreet = steps[0]?.streetName || 'la calle principal';
      const trafficText = currentRoute?.realWorld?.trafficLabel || 'tráfico habitual';
      speakAssistant(
        `Ruta más corta calculada por calles reales. Distancia aproximada: ${distKm} kilómetros. Tiempo de llegada: ${mins} minutos, tomando en cuenta ${trafficText.toLowerCase()}, lluvia y obstáculos viales. Comienza por ${firstStreet}.`
      );
    }
  }, [totalDistanceMeters, selectedRouteIndex]); // eslint-disable-line react-hooks/exhaustive-deps

  // 2. Silent Dynamic Rerouting Engine (Calculates new real-street routes in background without cuts or flashes)
  const silentReroute = useCallback(async (fromLat, fromLng) => {
    const now = Date.now();
    if (now - lastRerouteTimeRef.current < 3500) return;
    lastRerouteTimeRef.current = now;
    lastReroutePosRef.current = { lat: fromLat, lng: fromLng };

    try {
      const routerProfile = mode === 'walking' ? 'foot' : 'car';
      const osrmProfile = mode === 'walking' ? 'walking' : 'driving';
      const endpoints = [];
      if (MAPBOX_ACCESS_TOKEN) {
        const mapboxProfile = mode === 'walking' ? 'mapbox/walking' : 'mapbox/driving-traffic';
        endpoints.push(`https://api.mapbox.com/directions/v5/${mapboxProfile}/${fromLng},${fromLat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true&alternatives=false&language=es&annotations=duration,distance&access_token=${encodeURIComponent(MAPBOX_ACCESS_TOKEN)}`);
      }
      endpoints.push(
        `https://routing.openstreetmap.de/routed-${routerProfile}/route/v1/${osrmProfile}/${fromLng},${fromLat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true&alternatives=false`,
        `https://router.project-osrm.org/route/v1/${osrmProfile}/${fromLng},${fromLat};${destLng},${destLat}?overview=full&geometries=geojson&steps=true&alternatives=false`
      );

      for (const url of endpoints) {
        try {
          const res = await fetch(url, { signal: AbortSignal.timeout(6000) });
          if (!res.ok) continue;
          const data = await res.json();
          if (data.routes && data.routes.length > 0) {
            const r = data.routes[0];
            const rawCoords = r.geometry.coordinates.map(([lng, lat]) => [lat, lng]);
            const legSteps = r.legs?.[0]?.steps || [];
            const leg = r.legs?.[0];
            const summary = leg?.summary || 'Ruta en tiempo real';

            const maneuvers = legSteps.map((step, idx) => {
              const mType = step.maneuver?.type;
              const modifier = step.maneuver?.modifier;
              const streetName = step.name ? step.name.trim() : '';

              let icon = 'straight';
              if (modifier?.includes('left')) icon = 'left';
              else if (modifier?.includes('right')) icon = 'right';
              else if (mType === 'roundabout') icon = 'roundabout';
              else if (idx === legSteps.length - 1) icon = 'destination';

              let instruction = '';
              if (idx === legSteps.length - 1) {
                instruction = `Llegada a tu destino: ${streetName || displayDestName}`;
              } else if (idx === 0) {
                instruction = streetName ? `Continúa por ${streetName}` : 'Continúa por la vía';
              } else if (mType === 'turn' || mType === 'fork') {
                const dir = modifier === 'left' ? 'la izquierda' : modifier === 'right' ? 'la derecha' : 'adelante';
                instruction = streetName ? `Gira a ${dir} en ${streetName}` : `Gira a ${dir}`;
              } else if (mType === 'roundabout') {
                instruction = streetName ? `En la rotonda, toma la salida hacia ${streetName}` : 'En la rotonda, toma la salida';
              } else {
                instruction = streetName ? `Avanza por ${streetName}` : 'Continúa recto por la vía';
              }

              return {
                instruction,
                streetName: streetName || 'Vía en curso',
                distance: step.distance,
                duration: step.duration,
                location: [step.maneuver?.location?.[1] || rawCoords[0][0], step.maneuver?.location?.[0] || rawCoords[0][1]],
                icon,
              };
            });

            const realWorld = calculateRealWorldFactors({
              distanceMeters: r.distance,
              baseDurationSeconds: r.duration,
              mode,
              maneuvers,
              incidents: leg?.incidents || [],
              closures: leg?.closures || [],
            });

            const updatedRoute = {
              id: 'live-route',
              title: 'Ruta en tiempo real (Calles reales)',
              summary,
              coords: rawCoords,
              distanceMeters: r.distance,
              durationSeconds: realWorld.totalAdjustedSeconds,
              baseDurationSeconds: r.duration,
              typicalDurationSeconds: r.duration_typical || null,
              trafficDelaySeconds: realWorld.trafficDelayMins * 60,
              trafficAware: true,
              realWorld,
              incidents: leg?.incidents || [],
              closures: leg?.closures || [],
              averageCongestion: null,
              updatedAt: new Date().toISOString(),
              steps: maneuvers,
            };

            setAvailableRoutes([updatedRoute]);
            setSelectedRouteIndex(0);
            return;
          }
        } catch {
          // Continue to next endpoint fallback
        }
      }
    } catch (err) {
      console.warn('Error en silentReroute:', err);
    }
  }, [mode, destLat, destLng, displayDestName]);

  useEffect(() => {
    silentRerouteRef.current = silentReroute;
  }, [silentReroute]);

  // 3. Continuous 60fps Real-Time Navigation Loop (Smooth LERP interpolation without jumps or cuts)
  useEffect(() => {
    if (!isNavigating) {
      if (animRef.current) cancelAnimationFrame(animRef.current);
      return;
    }

    let lastFrameTime = performance.now();
    let virtualSimIndex = simIndex;

    const animate = (time) => {
      const dt = Math.min((time - lastFrameTime) / 1000, 0.1);
      lastFrameTime = time;

      const current = currentVehiclePosRef.current;
      const target = targetVehiclePosRef.current;

      const dLat = target[0] - current[0];
      const dLng = target[1] - current[1];
      const dist = Math.hypot(dLat, dLng);

      const isGpsActive = isTracking && lastGpsPositionRef.current;

      if (isGpsActive) {
        // Physical Real-time GPS movement tracking: smooth gliding interpolation
        if (dist > 0.000002) {
          const lerpFactor = Math.min(1, dt * 7); // Smooth fluid motion
          current[0] += dLat * lerpFactor;
          current[1] += dLng * lerpFactor;
          currentVehiclePosRef.current = [current[0], current[1]];
          setSmoothVehiclePos([current[0], current[1]]);

          const targetBearing = calculateBearing(current[0], current[1], target[0], target[1]);
          if (dist > 0.00001) {
            setCurrentBearing((prev) => {
              const diff = ((targetBearing - prev + 540) % 360) - 180;
              return ((prev + diff * 0.18 + 360) % 360);
            });
          }
        }
      } else if (routeCoordinates.length > 1) {
        // Desktop / Preview Simulation: advance along real street route points at 60fps
        const speedMultiplier = simSpeed * 1.6;
        const nextCoord = routeCoordinates[Math.min(Math.floor(virtualSimIndex) + 1, routeCoordinates.length - 1)];
        if (nextCoord) {
          targetVehiclePosRef.current = nextCoord;
          const lerpFactor = Math.min(1, dt * 4 * speedMultiplier);
          current[0] += (nextCoord[0] - current[0]) * lerpFactor;
          current[1] += (nextCoord[1] - current[1]) * lerpFactor;
          currentVehiclePosRef.current = [current[0], current[1]];
          setSmoothVehiclePos([current[0], current[1]]);

          const b = calculateBearing(current[0], current[1], nextCoord[0], nextCoord[1]);
          setCurrentBearing(b);

          if (Math.hypot(nextCoord[0] - current[0], nextCoord[1] - current[1]) < 0.00009) {
            virtualSimIndex += 1;
            setSimIndex(Math.min(virtualSimIndex, routeCoordinates.length - 1));
            if (virtualSimIndex >= routeCoordinates.length - 1) {
              setIsNavigating(false);
              setHasReachedDestination(true);
              speakAssistant(`Has llegado a tu destino: ${displayDestName}.`);
              return;
            }
          }
        }
      }

      // Check arrival at house
      const distToDest = L.latLng(current[0], current[1]).distanceTo(L.latLng(destLat, destLng));
      if (distToDest <= 25 && !hasReachedDestination) {
        setHasReachedDestination(true);
        setIsNavigating(false);
        speakAssistant(`Has llegado a tu destino: ${displayDestName}.`);
        return;
      }

      animRef.current = requestAnimationFrame(animate);
    };

    animRef.current = requestAnimationFrame(animate);
    return () => {
      if (animRef.current) cancelAnimationFrame(animRef.current);
    };
  }, [isNavigating, isTracking, routeCoordinates, simSpeed, displayDestName, destLat, destLng, hasReachedDestination, speakAssistant, simIndex]);

  // Maneuver-by-maneuver voice guidance
  useEffect(() => {
    if (!isNavigating || steps.length === 0 || !smoothVehiclePos) return;
    const userLatLng = L.latLng(smoothVehiclePos[0], smoothVehiclePos[1]);
    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      if (step.location) {
        const stepLatLng = L.latLng(step.location[0], step.location[1]);
        const dist = userLatLng.distanceTo(stepLatLng);
        if (dist <= 40 && lastSpokenStepRef.current !== i) {
          lastSpokenStepRef.current = i;
          speakAssistant(step.instruction);
          break;
        }
      }
    }
  }, [isNavigating, smoothVehiclePos, steps, speakAssistant]);

  const currentVehiclePos = smoothVehiclePos || [originLat, originLng];

  const distanceKm = (totalDistanceMeters / 1000).toFixed(1);
  const durationMins = Math.max(3, Math.round(totalDurationSeconds / 60));
  const trafficDelayMins = Math.round((currentRoute?.trafficDelaySeconds || 0) / 60);
  const trafficIssueCount = (currentRoute?.incidents?.length || 0) + (currentRoute?.closures?.length || 0);
  const routeAlert = currentRoute?.closures?.length
    ? { level: 'danger', text: `Se detectaron ${currentRoute.closures.length} cierre(s) en la ruta. Se priorizó una alternativa sin bloqueo cuando estuvo disponible.` }
    : currentRoute?.incidents?.length
      ? { level: 'danger', text: `Hay ${currentRoute.incidents.length} incidente(s) reportado(s). Conduce con precaución y sigue los desvíos indicados.` }
      : trafficDelayMins >= 5 || (currentRoute?.averageCongestion || 0) >= 60
        ? { level: 'warning', text: `Tráfico fuerte detectado: demora aproximada de ${Math.max(trafficDelayMins, 1)} minuto(s). La ruta seleccionada ofrece el mejor tiempo disponible.` }
        : currentRoute?.trafficAware
          ? null
          : { level: 'info', text: 'No hay cobertura de tráfico en vivo. La ruta se calcula con calles disponibles y tiempo estimado, sin incidentes en tiempo real.' };

  useEffect(() => {
    if (!routeAlert || routeAlert.level === 'info' || routeAlert.text === lastRouteAlertRef.current) return;
    lastRouteAlertRef.current = routeAlert.text;
    speakAssistant(`Alerta de ruta. ${routeAlert.text}`);
  }, [routeAlert?.level, routeAlert?.text, speakAssistant]);

  const distanceToDestMeters = smoothVehiclePos && destLat && destLng
    ? L.latLng(smoothVehiclePos[0], smoothVehiclePos[1]).distanceTo(L.latLng(destLat, destLng))
    : totalDistanceMeters;
  const progressPercent = totalDistanceMeters > 0
    ? Math.min(100, Math.max(0, Math.round(((totalDistanceMeters - distanceToDestMeters) / totalDistanceMeters) * 100)))
    : (routeCoordinates.length > 1 ? Math.round((simIndex / (routeCoordinates.length - 1)) * 100) : 0);

  const currentNextStep = steps[0] || {
    instruction: `Avanza directo hacia ${displayDestName || 'tu destino'}`,
    streetName: 'Vía principal',
    distance: 250,
    icon: 'straight'
  };

  // Fullscreen toggle
  const handleToggleFullscreen = () => {
    if (!containerRef.current) return;
    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen?.();
      setIsFullScreen(true);
    } else {
      document.exitFullscreen?.();
      setIsFullScreen(false);
    }
  };

  // Zoom controls
  const handleZoomIn = () => {
    if (mapInstanceRef.current) mapInstanceRef.current.zoomIn();
  };
  const handleZoomOut = () => {
    if (mapInstanceRef.current) mapInstanceRef.current.zoomOut();
  };

  // Focus: Where the person is
  const handleFocusOrigin = () => {
    setFollowVehicle(false);
    setTargetFocus([originLat, originLng]);
    speakAssistant('Mostrando tu ubicación actual.');
  };

  // Focus: Where the house is
  const handleFocusDestination = () => {
    setFollowVehicle(false);
    setTargetFocus([destLat, destLng]);
    speakAssistant(`Mostrando la ubicación de destino: ${displayDestName}.`);
  };

  // Focus: View entire route
  const handleRecenterRoute = () => {
    setFollowVehicle(false);
    setTargetFocus(null);
    speakAssistant('Mostrando la ruta completa.');
    if (mapInstanceRef.current && routeCoordinates.length > 0) {
      const allPoints = [...routeCoordinates, [originLat, originLng], [destLat, destLng]];
      const b = L.latLngBounds(allPoints);
      mapInstanceRef.current.fitBounds(b, {
        paddingTopLeft: [50, 140],
        paddingBottomRight: [50, 160],
        maxZoom: 15,
        animate: true,
      });
    }
  };

  // Real GPS hardware sync — Continuous tracking mode
  const handleGetCurrentGPS = () => {
    if (!navigator.geolocation) {
      speakAssistant('Tu navegador no permite acceso al sensor GPS.');
      return;
    }

    if (gpsWatchRef.current) {
      navigator.geolocation.clearWatch(gpsWatchRef.current);
      gpsWatchRef.current = null;
    }

    setGpsLoading(true);
    bestGpsAccuracyRef.current = Infinity;
    lastGpsPositionRef.current = null;
    lastGpsUpdateRef.current = 0;
    speakAssistant(isTracking
      ? 'Actualizando tu ubicación GPS y recalculando la ruta.'
      : 'Activando rastreo GPS en tiempo real. Esperando una señal precisa.');

    const acceptGpsPosition = (pos) => {
      const accuracy = Number(pos.coords.accuracy) || Infinity;
      // Reject only readings that are dramatically worse. A moving user's
      // newest position must still be accepted even if its accuracy varies.
      if (Number.isFinite(bestGpsAccuracyRef.current) && accuracy > Math.max(250, bestGpsAccuracyRef.current * 4)) return;

      bestGpsAccuracyRef.current = Math.min(bestGpsAccuracyRef.current, accuracy);
      const newCoords = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      const previous = lastGpsPositionRef.current;
      const movedMeters = previous
        ? L.latLng(previous.lat, previous.lng).distanceTo(L.latLng(newCoords.lat, newCoords.lng))
        : Infinity;
      const elapsed = Date.now() - lastGpsUpdateRef.current;
      // Avoid recalculating for harmless GPS jitter, but update continuously when moving
      if (previous && movedMeters < 3 && elapsed < 2000) return;

      lastGpsPositionRef.current = newCoords;
      lastGpsUpdateRef.current = Date.now();
      setGpsAccuracy(Number.isFinite(accuracy) ? Math.round(accuracy) : null);
      setGpsLoading(false);
      setIsTracking(true);
      setCustomOriginName('Tu ubicación GPS');

      targetVehiclePosRef.current = [newCoords.lat, newCoords.lng];

      // Arrival check at destination house (within 25m)
      const distToDest = L.latLng(newCoords.lat, newCoords.lng).distanceTo(L.latLng(destLat, destLng));
      if (distToDest <= 25) {
        setHasReachedDestination(true);
        setIsNavigating(false);
        speakAssistant(`¡Has llegado a tu destino: ${displayDestName}!`);
        return;
      }

      if (!isNavigatingRef.current) {
        setLiveOrigin(newCoords);
        setTargetFocus([newCoords.lat, newCoords.lng]);
        currentVehiclePosRef.current = [newCoords.lat, newCoords.lng];
        setSmoothVehiclePos([newCoords.lat, newCoords.lng]);
      } else {
        // Active real-time navigation: recalculate route along real streets dynamically without cuts!
        const distFromLastReroute = lastReroutePosRef.current
          ? L.latLng(newCoords.lat, newCoords.lng).distanceTo(L.latLng(lastReroutePosRef.current.lat, lastReroutePosRef.current.lng))
          : Infinity;
        if (distFromLastReroute >= 35 || (elapsed >= 15000 && distFromLastReroute >= 15)) {
          silentRerouteRef.current?.(newCoords.lat, newCoords.lng);
        }
      }
    };

    // Ask for a fresh high-accuracy fix before starting continuous updates.
    navigator.geolocation.getCurrentPosition(acceptGpsPosition, () => {}, {
      enableHighAccuracy: true,
      timeout: 15000,
      maximumAge: 0,
    });

    // Start continuous GPS tracking
    gpsWatchRef.current = navigator.geolocation.watchPosition(
      acceptGpsPosition,
      (err) => {
        setGpsLoading(false);
        if (!lastGpsPositionRef.current) {
          setIsTracking(false);
          speakAssistant('No se pudo obtener una ubicación GPS nueva. Revisa el permiso de ubicación del navegador.');
        }
      },
      { enableHighAccuracy: true, timeout: 20000, maximumAge: 0 }
    );
  };

  // Cleanup GPS watch on unmount
  useEffect(() => {
    return () => {
      if (gpsWatchRef.current) {
        navigator.geolocation.clearWatch(gpsWatchRef.current);
      }
    };
  }, []);

  // Start or Pause real-time navigation
  const handleToggleNavigation = () => {
    if (hasReachedDestination) {
      setHasReachedDestination(false);
      setSimIndex(0);
      currentVehiclePosRef.current = [originLat, originLng];
      targetVehiclePosRef.current = [originLat, originLng];
      setSmoothVehiclePos([originLat, originLng]);
    }

    const nextNav = !isNavigating;
    setIsNavigating(nextNav);

    if (nextNav) {
      setFollowVehicle(true);
      if (!isTracking) {
        handleGetCurrentGPS();
      }
      speakAssistant('Iniciando recorrido en tiempo real hacia tu destino. Sigue la ruta trazada.');
    } else {
      speakAssistant('Recorrido pausado.');
    }
  };

  // Reset navigation
  const handleResetNavigation = () => {
    setIsNavigating(false);
    setHasReachedDestination(false);
    setSimIndex(0);
    currentVehiclePosRef.current = [originLat, originLng];
    targetVehiclePosRef.current = [originLat, originLng];
    setSmoothVehiclePos([originLat, originLng]);
    lastSpokenStepRef.current = -1;
    speakAssistant('Recorrido reiniciado.');
  };

  // Handle new destination from search
  const handleNewDestination = (coords, name) => {
    setLiveDestination(coords);
    setCustomDestName(name.split(',').slice(0, 2).join(', '));
    setSimIndex(0);
    setIsNavigating(false);
    setSelectedRouteIndex(0);
    setShowSearchPanel(false);
    setTargetFocus(null);
  };

  // Handle new origin from search
  const handleNewOrigin = (coords, name) => {
    // If setting custom origin, stop live GPS watch so it doesn't overwrite immediately
    if (gpsWatchRef.current) {
      navigator.geolocation?.clearWatch(gpsWatchRef.current);
      gpsWatchRef.current = null;
    }
    setIsTracking(false);
    setGpsAccuracy(null);
    lastGpsPositionRef.current = null;
    lastGpsUpdateRef.current = 0;
    setLiveOrigin(coords);
    setCustomOriginName(name.split(',').slice(0, 2).join(', '));
    setSimIndex(0);
    setIsNavigating(false);
    setSelectedRouteIndex(0);
    setShowSearchPanel(false);
    setTargetFocus(null);
  };

  // Public tile providers. CARTO was removed because it returns
  // "API KEY REQUIRED" for this project.
  const activeTileLayer = useMemo(() => {
    if (mapTheme === 'satelite') return {
      url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
      attribution: 'Tiles &copy; Esri — Source: Esri, Maxar, Earthstar Geographics',
      maxNativeZoom: 19,
      maxZoom: 20,
    };
    if (mapTheme === 'relieve') return {
      url: 'https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png',
      attribution: 'Map data &copy; OpenStreetMap contributors, SRTM | Map style &copy; OpenTopoMap',
      maxNativeZoom: 17,
      maxZoom: 19,
    };
    return {
      url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
      attribution: '&copy; OpenStreetMap contributors',
      maxNativeZoom: 19,
      maxZoom: 20,
    };
  }, [mapTheme]);

  return (
    <div
      ref={containerRef}
      className="relative w-full h-full min-h-[550px] overflow-hidden rounded-[28px] bg-[#F7F0E6] select-none ring-1 ring-[#3B2118]/15"
      style={{ boxShadow: '0 24px 70px rgba(59,33,24,.16), 0 3px 12px rgba(59,33,24,.08)' }}
    >
      {/* ── TOP RUWAJAY PREMIUM NAVIGATION HUD ── */}
      <div className="absolute top-0 left-0 right-0 z-20 pointer-events-none">
        
        {/* Glassmorphism Top Bar */}
        <div className="pointer-events-auto m-3 flex flex-col gap-2.5">
          
          {/* Main Instruction Bar — Premium emerald glassmorphism */}
          <div
            className="flex items-center justify-between gap-3 p-3 sm:px-4 sm:py-3.5 rounded-[22px]"
            style={{
              background: 'linear-gradient(135deg, rgba(6, 78, 59, 0.96) 0%, rgba(4, 120, 87, 0.92) 50%, rgba(6, 95, 70, 0.96) 100%)',
              backdropFilter: 'blur(20px)',
              border: '1px solid rgba(52, 211, 153, 0.3)',
              boxShadow: '0 14px 38px rgba(4, 40, 28, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.18)',
            }}
          >
            {/* Next Maneuver Info */}
            <div className="flex items-center gap-3 min-w-0 flex-1">
              <div
                className="w-11 h-11 sm:w-12 sm:h-12 rounded-[14px] flex items-center justify-center shrink-0"
                style={{
                  background: '#D84420',
                  boxShadow: '0 6px 16px rgba(216,68,32,.32)',
                  border: '1.5px solid rgba(255,255,255,0.25)',
                }}
              >
                {currentNextStep.icon === 'left' ? (
                  <CornerDownLeft size={24} strokeWidth={2.8} className="text-white" />
                ) : currentNextStep.icon === 'right' ? (
                  <CornerDownRight size={24} strokeWidth={2.8} className="text-white" />
                ) : currentNextStep.icon === 'destination' ? (
                  <Flag size={24} strokeWidth={2.8} className="text-white" />
                ) : (
                  <ArrowUp size={24} strokeWidth={2.8} className="text-white" />
                )}
              </div>
              
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-[10px] sm:text-xs font-black uppercase tracking-wider text-[#D4962A]">
                    Próxima maniobra · {Math.round(currentNextStep.distance || 180)}m
                  </span>
                  {isTracking && (
                    <span className="inline-flex items-center gap-1 text-[9px] font-bold bg-[#10B981]/25 px-2 py-0.5 rounded-full text-[#10B981] border border-[#10B981]/30">
                      <Signal size={9} className="animate-pulse" /> GPS Activo
                    </span>
                  )}
                </div>
                <p className="text-xs sm:text-sm font-extrabold text-white truncate max-w-xs sm:max-w-md mt-0.5">
                  {currentNextStep.instruction}
                </p>
              </div>
            </div>

            {/* Controls */}
            <div className="flex items-center gap-1.5 shrink-0">
              
              {/* Search / Change Route Button */}
              <button
                onClick={() => setShowSearchPanel(!showSearchPanel)}
                className={`flex items-center gap-1 px-2.5 py-2 rounded-xl transition-all border text-xs font-black ${
                  showSearchPanel
                    ? 'bg-[#D4962A] text-[#3B2118] border-[#D4962A] shadow-lg'
                    : 'bg-white/10 text-white/90 border-white/15 hover:bg-white/20'
                }`}
                title="Buscar dirección o cambiar ruta"
              >
                <Search size={15} strokeWidth={2.5} />
                <span className="hidden sm:inline">Buscar / Ruta</span>
              </button>

              {/* Spanish Voice Assistant Toggle Group */}
              <div className="flex items-center rounded-xl bg-white/10 border border-white/15 overflow-hidden">
                <button
                  onClick={() => {
                    const nextState = !voiceEnabled;
                    setVoiceEnabled(nextState);
                    if (nextState) {
                      speakAssistant('Asistente de voz RuwaJay activado.');
                    } else if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
                      window.speechSynthesis.cancel();
                    }
                  }}
                  className={`flex items-center gap-1.5 px-2.5 py-2 text-xs font-black transition-all ${
                    voiceEnabled
                      ? 'bg-[#D4962A] text-[#3B2118] shadow-sm'
                      : 'text-white/70 hover:text-white'
                  }`}
                  title={
                    voiceEnabled
                      ? `Desactivar voz de asistente (${activeSpanishVoice?.name || 'Español'})`
                      : 'Activar voz en español'
                  }
                >
                  {voiceEnabled ? (
                    <>
                      {isSpeaking ? (
                        <div className="flex items-end gap-0.5 h-3.5">
                          <span className="w-0.5 bg-[#3B2118] rounded-full ruwa-wave-bar-1" />
                          <span className="w-0.5 bg-[#3B2118] rounded-full ruwa-wave-bar-2" />
                          <span className="w-0.5 bg-[#3B2118] rounded-full ruwa-wave-bar-3" />
                          <span className="w-0.5 bg-[#3B2118] rounded-full ruwa-wave-bar-4" />
                        </div>
                      ) : (
                        <Volume2 size={15} />
                      )}
                      <span className="hidden md:inline">
                        {detectedDaliaVoice ? 'Dalia' : activeSpanishVoice ? 'Voz' : 'Voz'}
                      </span>
                    </>
                  ) : (
                    <>
                      <VolumeX size={15} />
                      <span className="hidden md:inline">Mute</span>
                    </>
                  )}
                </button>

                {/* Voice Dialect & Audio Settings */}
                <button
                  onClick={() => setShowVoiceMenu(!showVoiceMenu)}
                  className={`p-2 transition-colors border-l border-white/15 ${
                    showVoiceMenu ? 'bg-[#D4962A]/40 text-[#D4962A]' : 'text-white/70 hover:text-white'
                  }`}
                  title="Configurar acento del asistente (Latino / España)"
                >
                  <SlidersHorizontal size={13} />
                </button>
              </div>

              {/* Tile Mode Tabs — Premium glass tabs */}
              <div
                className="flex items-center rounded-xl p-0.5"
                style={{
                  background: 'rgba(255,255,255,0.08)',
                  border: '1px solid rgba(255,255,255,0.12)',
                }}
              >
                <button
                  onClick={() => setMapTheme('calles')}
                  className={`px-2.5 py-1.5 text-[11px] font-black rounded-lg transition-all ${
                    mapTheme === 'calles'
                      ? 'bg-[#FFF5E8] text-[#0B5D3B] shadow-sm'
                      : 'text-white/70 hover:text-white'
                  }`}
                  title="Mapa de Calles"
                >
                  <MapIcon size={14} className="inline mr-0.5 -mt-0.5" />
                  <span className="hidden sm:inline"> Calles</span>
                </button>
                <button
                  onClick={() => setMapTheme('satelite')}
                  className={`px-2.5 py-1.5 text-[11px] font-black rounded-lg transition-all ${
                    mapTheme === 'satelite'
                      ? 'bg-[#0B5D3B] text-white shadow-sm border border-[#D4962A]/60'
                      : 'text-white/70 hover:text-white'
                  }`}
                  title="Vista Satelital"
                >
                  <Satellite size={14} className="inline mr-0.5 -mt-0.5" />
                  <span className="hidden sm:inline"> Satélite</span>
                </button>
                <button
                  onClick={() => setMapTheme('relieve')}
                  className={`px-2.5 py-1.5 text-[11px] font-black rounded-lg transition-all ${
                    mapTheme === 'relieve'
                      ? 'bg-[#D84420] text-white shadow-sm'
                      : 'text-white/70 hover:text-white'
                  }`}
                  title="Mapa de relieve y curvas de nivel"
                >
                  <Pencil size={14} className="inline mr-0.5 -mt-0.5" />
                  <span className="hidden sm:inline"> Relieve</span>
                </button>
              </div>

              {/* Step list drawer button */}
              <button
                onClick={() => setShowStepDrawer(!showStepDrawer)}
                className={`hidden sm:flex items-center gap-1 px-3 py-2 rounded-xl text-xs font-bold transition-all border ${
                  showStepDrawer
                    ? 'bg-[#D84420] text-white border-[#D84420]'
                    : 'bg-white/10 hover:bg-white/20 text-white border-white/10'
                }`}
                title="Ver lista de pasos"
              >
                <Layers size={14} />
                <span>{steps.length}</span>
              </button>

              {/* Fullscreen button */}
              <button
                onClick={handleToggleFullscreen}
                className="p-2 rounded-xl bg-white/10 hover:bg-white/20 text-white transition-colors border border-white/10"
                title={isFullScreen ? 'Salir de pantalla completa' : 'Pantalla completa'}
              >
                {isFullScreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
              </button>
            </div>
          </div>

          {/* Voice Settings Popover - Exclusively Microsoft Dalia (Spanish) */}
          {showVoiceMenu && (
            <div
              className="p-4 sm:p-5 rounded-[22px] pointer-events-auto w-full max-w-[420px] ml-auto text-[#3B2118]"
              style={{
                background: 'rgba(255, 250, 242, .98)',
                backdropFilter: 'blur(24px)',
                border: '1px solid rgba(59,33,24,.12)',
                boxShadow: '0 22px 60px rgba(59,33,24,.22), 0 2px 8px rgba(59,33,24,.08)',
                animation: 'slideDown 0.2s ease-out',
              }}
            >
              <div className="flex items-start justify-between gap-4 pb-3 mb-3 border-b border-[#3B2118]/10">
                <div className="flex items-center gap-3">
                  <span className="grid h-10 w-10 place-items-center rounded-xl bg-[#0B5D3B] text-[#FFF5E8] shadow-sm">
                    <Volume2 size={18} />
                  </span>
                  <div>
                    <span className="block text-[10px] font-black tracking-[.16em] text-[#D84420] uppercase">Navegación por voz</span>
                    <span className="block text-sm font-black text-[#3B2118]">Asistente de Voz en Español</span>
                  </div>
                </div>
                <button onClick={() => setShowVoiceMenu(false)} className="grid h-8 w-8 place-items-center rounded-full bg-[#3B2118]/5 text-[#3B2118]/55 hover:bg-[#3B2118]/10 hover:text-[#3B2118] transition-colors" aria-label="Cerrar configuración de voz">
                  <X size={15} />
                </button>
              </div>

              <p className="text-xs leading-relaxed text-[#6F5A50] mb-3 font-medium">
                Revisa la voz detectada por tu navegador y escucha una prueba antes de iniciar el recorrido.
              </p>

              {/* Voice card: shows Dalia if available, otherwise the active Spanish fallback */}
              <div className="p-3.5 rounded-2xl bg-white border border-[#E8D9C8] shadow-[0_6px_20px_rgba(59,33,24,.07)] mb-3">
                <div className="flex items-center justify-between gap-2">
                  <div className="flex items-center gap-2.5">
                    <div className="w-10 h-10 rounded-xl bg-[#FFF0DA] text-[#D84420] flex items-center justify-center shrink-0">
                      <Mic size={18} />
                    </div>
                    <div>
                      <span className="block font-black text-xs text-[#3B2118] line-clamp-1">
                        {activeSpanishVoice ? activeSpanishVoice.name : 'Sin voz en español disponible'}
                      </span>
                      <span className="block text-[10px] text-[#7A685F] font-semibold mt-0.5">
                        {detectedDaliaVoice
                          ? `Microsoft Dalia · ${detectedDaliaVoice.lang}`
                          : activeSpanishVoice
                            ? `Voz del navegador · ${activeSpanishVoice.lang}`
                            : 'No se encontró ninguna voz en español en tu navegador'}
                      </span>
                    </div>
                  </div>
                  <span className={`inline-flex items-center gap-1 text-[9px] font-black px-2 py-0.5 rounded-full border ${
                    activeSpanishVoice
                      ? 'text-[#087A4B] bg-[#E8F7EF] border-[#BDE7CF]'
                      : 'text-[#A45E08] bg-[#FFF4D9] border-[#F2D18A]'
                  }`}>
                    {activeSpanishVoice ? <><Check size={10} /> Activa</> : <><AlertCircle size={10} /> No disponible</>}
                  </span>
                </div>
              </div>

              {/* Test Voice button */}
              <button
                onClick={() => {
                  speakAssistant('¡Hola! Soy tu asistente de voz en español de RuwaJay. Te guiaré paso a paso por la ruta más corta hacia tu vivienda.');
                }}
                className="w-full min-h-11 flex items-center justify-center gap-2 py-2.5 px-4 rounded-xl bg-[#D84420] hover:bg-[#C93D1C] text-white text-xs font-black shadow-[0_7px_18px_rgba(216,68,32,.24)] transition-all active:scale-[.98]"
              >
                <Mic size={14} />
                <span>Escuchar prueba de voz</span>
              </button>
            </div>
          )}

          {/* Subtitle / Live Transcription Banner */}
          {showSubtitle && lastSpokenText && (
            <div
              className="pointer-events-auto flex items-center justify-between gap-2 px-4 py-2.5 rounded-2xl border text-[#3B2118]"
              style={{
                background: 'rgba(255,250,242,.97)',
                backdropFilter: 'blur(18px)',
                borderColor: 'rgba(59,33,24,.12)',
                boxShadow: '0 10px 30px rgba(59,33,24,.16)',
                animation: 'slideDown 0.2s ease-out',
              }}
            >
              <div className="flex items-center gap-2.5 min-w-0 flex-1">
                {/* Animated equalizer waves */}
                <div className="flex items-end gap-0.5 h-3.5 shrink-0">
                  <span className="w-1 bg-[#D4962A] rounded-full ruwa-wave-bar-1" />
                  <span className="w-1 bg-[#10B981] rounded-full ruwa-wave-bar-2" />
                  <span className="w-1 bg-[#D4962A] rounded-full ruwa-wave-bar-3" />
                  <span className="w-1 bg-[#10B981] rounded-full ruwa-wave-bar-4" />
                </div>
                <span className="text-[10px] font-black uppercase tracking-wider text-[#D84420] shrink-0">
                  {detectedDaliaVoice ? 'Dalia' : 'Asistente'}
                </span>
                <p className="text-xs font-bold text-[#3B2118] truncate">
                  {lastSpokenText}
                </p>
              </div>
              <button
                onClick={() => setShowSubtitle(false)}
                className="text-[#3B2118]/35 hover:text-[#3B2118] transition-colors p-1"
              >
                <X size={12} />
              </button>
            </div>
          )}

          {/* Address Search Panel — Slide-in */}
          {showSearchPanel && (
            <div
              className="p-4 rounded-[22px] pointer-events-auto"
              style={{
                background: 'linear-gradient(135deg, rgba(6, 78, 59, 0.98) 0%, rgba(4, 120, 87, 0.95) 100%)',
                backdropFilter: 'blur(20px)',
                border: '1px solid rgba(52, 211, 153, 0.35)',
                boxShadow: '0 18px 45px rgba(4, 40, 28, 0.35)',
                animation: 'slideDown 0.25s ease-out',
              }}
            >
              <div className="flex items-center justify-between gap-2 mb-2.5">
                <div className="flex items-center gap-2">
                  <Navigation2 size={15} className="text-[#F59E0B]" />
                  <span className="text-[11px] font-black text-[#F59E0B] uppercase tracking-wider">
                    Buscar Dirección · Cambiar Ruta en Vivo
                  </span>
                </div>
                <button
                  onClick={() => setShowSearchPanel(false)}
                  className="text-white/40 hover:text-white transition-colors p-1"
                >
                  <X size={14} />
                </button>
              </div>
              <AddressSearchBar
                onSelectDestination={handleNewDestination}
                onSelectOrigin={handleNewOrigin}
                speakAssistant={speakAssistant}
                currentDestAddress={displayDestName}
                currentOriginAddress={customOriginName || (isTracking ? 'Tu Ubicación GPS en Vivo' : 'Tu Ubicación')}
                onUseCurrentGPS={handleGetCurrentGPS}
                isTracking={isTracking}
              />
              <div className="flex items-center justify-between text-[10px] text-white/60 font-bold mt-2 pt-2 border-t border-white/10">
                <span className="inline-flex items-center gap-1"><MapPin size={11} className="text-[#34D399]" /> Origen: <strong className="text-white/90">{customOriginName || (isTracking ? 'GPS en Vivo' : 'Ubicación actual')}</strong></span>
                <span className="inline-flex items-center gap-1"><Home size={11} className="text-[#F59E0B]" /> Destino: <strong className="text-white/90">{displayDestName}</strong></span>
              </div>
            </div>
          )}

          {/* Route Selector — Premium glassmorphism bar */}
          <div
            className="pointer-events-auto flex flex-wrap items-center justify-between gap-2 px-3 py-2 rounded-xl text-[11px]"
            style={{
              background: 'linear-gradient(135deg, rgba(15, 23, 42, 0.92) 0%, rgba(15, 23, 42, 0.88) 100%)',
              backdropFilter: 'blur(16px)',
              border: '1px solid rgba(255,255,255,0.12)',
              boxShadow: '0 4px 20px rgba(0,0,0,0.25)',
            }}
          >
            {/* Route Options Badges */}
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-extrabold uppercase text-[#F59E0B] flex items-center gap-1">
                <RouteIcon size={12} /> Rutas:
              </span>
              
              {availableRoutes.map((r, idx) => {
                const isShortest = idx === 0;
                const isSelected = selectedRouteIndex === idx;
                const distText = (r.distanceMeters / 1000).toFixed(1) + ' km';
                const timeText = Math.max(3, Math.round(r.durationSeconds / 60)) + ' min';

                return (
                  <button
                    key={r.id}
                    onClick={() => {
                      setSelectedRouteIndex(idx);
                      setSimIndex(0);
                      setSimulating(false);
                      speakAssistant(`Cambiando a ${isShortest ? 'la ruta más corta' : 'ruta alternativa'} de ${distText}.`);
                    }}
                    className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg font-black text-[10px] transition-all border ${
                      isSelected
                        ? 'bg-[#10B981] text-slate-950 border-[#10B981] shadow-md shadow-[#10B981]/30'
                        : 'bg-white/10 text-white/80 border-white/10 hover:bg-white/20'
                    }`}
                  >
                    <span className="inline-flex items-center gap-1">
                      {isShortest ? (r.trafficAware ? <Zap size={10} className="text-amber-300" /> : <Sparkles size={10} className="text-amber-300" />) : null}
                      {isShortest ? (r.trafficAware ? 'Rápida:' : 'Corta:') : 'Alt:'}
                    </span>
                    <span className="font-bold">{distText} ({timeText})</span>
                  </button>
                );
              })}
            </div>

            {/* Route summary */}
            <div className="flex items-center gap-3 text-[11px] font-bold">
              <span className={`inline-flex items-center gap-1 rounded-full px-2 py-1 ${
                currentRoute?.trafficAware
                  ? 'bg-emerald-400/15 text-emerald-300 border border-emerald-300/20'
                  : 'bg-amber-400/10 text-amber-200 border border-amber-300/20'
              }`}>
                <Radio size={11} className={currentRoute?.trafficAware ? 'animate-pulse' : ''} />
                {currentRoute?.trafficAware
                  ? `Tráfico en vivo${trafficIssueCount ? ` · ${trafficIssueCount} incidencia${trafficIssueCount === 1 ? '' : 's'}` : ''}`
                  : 'Estimación sin tráfico en vivo'}
              </span>
              <span className="text-white/70 truncate">
                Vía: <strong className="text-[#FFF5E8]">{routeSummary}</strong>
              </span>
            </div>
          </div>

          {routeAlert && (
            <div className={`flex items-start gap-2 border-y px-4 py-2.5 text-xs font-bold shadow-sm ${
              routeAlert.level === 'danger'
                ? 'border-red-300 bg-red-50 text-red-800'
                : routeAlert.level === 'warning'
                  ? 'border-amber-300 bg-amber-50 text-amber-900'
                  : 'border-sky-300 bg-sky-50 text-sky-800'
            }`}>
              <AlertCircle size={16} className="mt-0.5 shrink-0" />
              <span>{routeAlert.text}</span>
            </div>
          )}

          {/* Progress Bar during real-time navigation */}
          {isNavigating && (
            <div
              className="w-full h-2 rounded-full overflow-hidden"
              style={{
                background: 'rgba(11, 93, 59, 0.3)',
                backdropFilter: 'blur(4px)',
                border: '1px solid rgba(255,255,255,0.1)',
              }}
            >
              <div
                className="h-full transition-all duration-300 rounded-full"
                style={{
                  width: `${progressPercent}%`,
                  background: 'linear-gradient(90deg, #10B981 0%, #D4962A 50%, #D84420 100%)',
                  boxShadow: '0 0 12px rgba(16, 185, 129, 0.5)',
                }}
              />
            </div>
          )}
        </div>
      </div>

      {/* ── MAP CONTAINER OR VECTOR BLUEPRINT ── */}
      {mapTheme === 'plano' ? (
        /* ── BESPOKE VECTOR SCHEMATIC BLUEPRINT VIEW ── */
        <div className="w-full h-full min-h-[550px] bg-[#0F172A] relative overflow-hidden flex flex-col items-center justify-center p-6 select-none">
          <div
            className="absolute inset-0 opacity-10"
            style={{
              backgroundImage: 'radial-gradient(#10B981 1px, transparent 1px), radial-gradient(#10B981 1px, transparent 1px)',
              backgroundSize: '24px 24px',
              backgroundPosition: '0 0, 12px 12px',
            }}
          />

          <svg className="w-full h-full max-w-4xl max-h-[460px] relative z-10" viewBox="0 0 800 500" fill="none">
            <defs>
              <linearGradient id="ruwaVectorRouteGrad" x1="0%" y1="100%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#10B981" />
                <stop offset="50%" stopColor="#D4962A" />
                <stop offset="100%" stopColor="#D84420" />
              </linearGradient>
              <filter id="glow">
                <feGaussianBlur stdDeviation="4" result="coloredBlur"/>
                <feMerge>
                  <feMergeNode in="coloredBlur"/>
                  <feMergeNode in="SourceGraphic"/>
                </feMerge>
              </filter>
            </defs>

            {/* City blocks */}
            <g opacity="0.3">
              <rect x="60" y="80" width="130" height="90" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="220" y="70" width="160" height="100" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="410" y="60" width="180" height="110" rx="8" fill="rgba(11,93,59,0.3)" stroke="#10B981" strokeWidth="1.5" strokeDasharray="4 3" />
              <text x="440" y="115" fill="#10B981" fontSize="11" fontWeight="bold">Sector Residencial</text>

              <rect x="70" y="210" width="120" height="120" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="220" y="210" width="150" height="130" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="400" y="210" width="190" height="120" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="620" y="190" width="130" height="140" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />

              <rect x="90" y="370" width="180" height="80" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="300" y="370" width="160" height="80" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
              <rect x="490" y="360" width="230" height="90" rx="8" fill="#1E293B" stroke="#334155" strokeWidth="1.5" />
            </g>

            {/* Avenues */}
            <path d="M 30 190 L 770 190" stroke="#1E293B" strokeWidth="20" strokeLinecap="round" />
            <path d="M 30 190 L 770 190" stroke="#334155" strokeWidth="16" strokeLinecap="round" opacity="0.5" />
            <path d="M 30 350 L 770 350" stroke="#1E293B" strokeWidth="16" strokeLinecap="round" />
            <path d="M 30 350 L 770 350" stroke="#334155" strokeWidth="12" strokeLinecap="round" opacity="0.5" />
            <path d="M 205 30 L 205 470" stroke="#1E293B" strokeWidth="16" strokeLinecap="round" />
            <path d="M 205 30 L 205 470" stroke="#334155" strokeWidth="12" strokeLinecap="round" opacity="0.5" />
            <path d="M 390 30 L 390 470" stroke="#1E293B" strokeWidth="20" strokeLinecap="round" />
            <path d="M 390 30 L 390 470" stroke="#334155" strokeWidth="16" strokeLinecap="round" opacity="0.5" />
            <path d="M 605 30 L 605 470" stroke="#1E293B" strokeWidth="16" strokeLinecap="round" />
            <path d="M 605 30 L 605 470" stroke="#334155" strokeWidth="12" strokeLinecap="round" opacity="0.5" />

            {/* Glowing route line */}
            <path
              d="M 110 410 L 205 410 Q 205 350 205 350 L 390 350 L 390 190 L 605 190 L 605 120 L 670 120"
              stroke="#10B981"
              strokeWidth="16"
              strokeLinecap="round"
              strokeLinejoin="round"
              opacity="0.2"
              filter="url(#glow)"
            />
            <path
              d="M 110 410 L 205 410 Q 205 350 205 350 L 390 350 L 390 190 L 605 190 L 605 120 L 670 120"
              stroke="url(#ruwaVectorRouteGrad)"
              strokeWidth="6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            <path
              d="M 110 410 L 205 410 Q 205 350 205 350 L 390 350 L 390 190 L 605 190 L 605 120 L 670 120"
              stroke="#FFF5E8"
              strokeWidth="2.5"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeDasharray="8 14"
              className="ruwa-route-pulse-dash"
            />

            {/* Origin */}
            <g transform="translate(110, 410)">
              <circle r="20" fill="#10B981" fillOpacity="0.15" />
              <circle r="12" fill="#0B5D3B" fillOpacity="0.3" />
              <circle r="8" fill="#0B5D3B" stroke="#FFF5E8" strokeWidth="2.5" />
              <circle r="3" fill="#D4962A" />
              <text x="-35" y="28" fill="#FFF5E8" fontSize="10" fontWeight="bold">Mi ubicación</text>
            </g>

            {/* Destination */}
            <g transform="translate(670, 120)">
              <rect x="-20" y="-20" width="40" height="40" rx="12" fill="#D84420" stroke="#FFF5E8" strokeWidth="2.5" transform="rotate(-45)" />
              <g transform="translate(-10, -10)">
                <path d="M10 2L2 9V17H18V9L10 2Z" fill="#FFF5E8" />
              </g>
              <rect x="-60" y="-48" width="120" height="24" rx="8" fill="#0B5D3B" stroke="#D4962A" strokeWidth="1.5" />
              <text x="0" y="-32" fill="#FFF5E8" fontSize="10" fontWeight="900" textAnchor="middle">
                {propertyTitle.length > 18 ? propertyTitle.slice(0, 18) + '…' : propertyTitle}
              </text>
            </g>
          </svg>

          <div
            className="absolute bottom-24 left-4 z-10 px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2"
            style={{
              background: 'linear-gradient(135deg, rgba(11, 93, 59, 0.9) 0%, rgba(8, 74, 47, 0.9) 100%)',
              backdropFilter: 'blur(12px)',
              border: '1px solid rgba(212, 150, 42, 0.4)',
              color: '#FFF5E8',
            }}
          >
            <Sparkles size={14} className="text-[#D4962A]" />
            <span>Plano Vectorial · RuwaJay Maps</span>
          </div>
        </div>
      ) : (
        /* ── INTERACTIVE LEAFLET MAP WITH REAL STREETS ── */
        <MapContainer
          center={[originLat, originLng]}
          zoom={13}
          scrollWheelZoom={true}
          zoomControl={false}
          attributionControl={false}
          className="w-full h-full z-0 min-h-[550px]"
          ref={(m) => {
            if (m) mapInstanceRef.current = m;
          }}
        >
          {/* Tile Layer */}
          <TileLayer
            key={activeTileLayer.url}
            url={activeTileLayer.url}
            maxNativeZoom={activeTileLayer.maxNativeZoom}
            maxZoom={activeTileLayer.maxZoom}
            attribution={activeTileLayer.attribution}
            className={mapTheme === 'satelite' ? '' : 'ruwa-custom-map-tiles-premium'}
          />

          {/* Smart Auto Bounds Manager */}
          <MapBoundsController
            coordinates={routeCoordinates}
            origin={liveOrigin}
            destination={liveDestination}
            targetFocus={targetFocus}
            vehiclePos={smoothVehiclePos}
            followVehicle={followVehicle}
            isNavigating={isNavigating}
          />

          {/* Custom Floating Controls */}
          <CustomMapControls
            onZoomIn={handleZoomIn}
            onZoomOut={handleZoomOut}
            onFocusOrigin={handleFocusOrigin}
            onFocusDestination={handleFocusDestination}
            onRecenterRoute={handleRecenterRoute}
            onGetCurrentGPS={handleGetCurrentGPS}
            gpsLoading={gpsLoading}
            isTracking={isTracking}
          />

          {/* Alternative Route (Rendered softly if available) */}
          {alternativeRoute && alternativeRoute.coords.length > 1 && (
            <Polyline
              positions={alternativeRoute.coords}
              pathOptions={{
                color: '#94A3B8',
                weight: 5,
                opacity: 0.5,
                dashArray: '8, 10',
                lineCap: 'round',
                lineJoin: 'round',
              }}
              eventHandlers={{
                click: () => {
                  setSelectedRouteIndex(selectedRouteIndex === 0 ? 1 : 0);
                  speakAssistant('Cambiando a ruta alternativa.');
                },
              }}
            />
          )}

          {/* 1. Outer Glow Polyline Layer (Shortest Road Route) */}
          {routeCoordinates.length > 1 && (
            <Polyline
              positions={routeCoordinates}
              pathOptions={{
                color: '#10B981',
                weight: 12,
                opacity: 0.3,
                lineCap: 'round',
                lineJoin: 'round',
              }}
            />
          )}

          {/* 2. Core Solid Road Polyline Layer */}
          {routeCoordinates.length > 1 && (
            <Polyline
              positions={routeCoordinates}
              pathOptions={{
                color: '#059669',
                weight: 7,
                opacity: 0.98,
                lineCap: 'round',
                lineJoin: 'round',
              }}
            />
          )}

          {/* 3. Animated Pulse Ribbon */}
          {routeCoordinates.length > 1 && (
            <Polyline
              positions={routeCoordinates}
              pathOptions={{
                color: '#F59E0B',
                weight: 3,
                opacity: 0.95,
                dashArray: '10, 14',
                className: 'ruwa-route-pulse-dash',
                lineCap: 'round',
              }}
            />
          )}

          {isTracking && gpsAccuracy && (
            <Circle
              center={[originLat, originLng]}
              radius={gpsAccuracy}
              pathOptions={{ color: '#10B981', fillColor: '#10B981', fillOpacity: 0.12, weight: 1.5 }}
            />
          )}

          {/* Origin Marker (Where the person is) */}
          <Marker position={[originLat, originLng]} icon={createOriginIcon()}>
            <Popup>
              <div className="p-2 text-center font-sans max-w-[200px]">
                <span
                  className="inline-flex items-center gap-1 text-white text-[10px] font-black uppercase px-3 py-1 rounded-full mb-1.5 shadow-sm"
                  style={{ background: 'linear-gradient(135deg, #065F46, #059669)' }}
                >
                  <MapPin size={11} className="text-emerald-200" />
                  <span>{isTracking ? 'GPS en Vivo' : 'Tu Ubicación'}</span>
                </span>
                <p className="font-extrabold text-[#3B2118] text-xs">Punto de Partida</p>
                <p className="text-[10px] text-gray-500 mt-1">
                  {originLat.toFixed(5)}, {originLng.toFixed(5)}
                </p>
                {isTracking && gpsAccuracy && (
                  <p className={`text-[10px] font-bold mt-1 ${gpsAccuracy <= 50 ? 'text-emerald-600' : 'text-amber-600'}`}>
                    Precisión estimada: ±{gpsAccuracy} m
                  </p>
                )}
                <div className="mt-2 text-[10px] text-[#059669] font-bold bg-[#059669]/10 p-1.5 rounded-lg">
                  A {distanceKm} km por calles reales
                </div>
              </div>
            </Popup>
          </Marker>

          {/* Destination Marker (Where the house is) */}
          <Marker
            position={[destLat, destLng]}
            icon={createDestinationIcon(propertyPrice)}
          >
            <Popup>
              <div className="p-2 max-w-[220px] text-center font-sans">
                {propertyThumbnail && (
                  <img
                    src={propertyThumbnail}
                    alt={propertyTitle}
                    className="w-full h-28 object-cover rounded-xl mb-2 shadow-md"
                  />
                )}
                <span
                  className="inline-flex items-center gap-1 text-white text-[9px] font-black uppercase px-3 py-1 rounded-full mb-1.5 shadow-sm"
                  style={{ background: 'linear-gradient(135deg, #D84420, #F07824)' }}
                >
                  <Home size={11} className="text-white" />
                  <span>Destino Confirmado</span>
                </span>
                <p className="font-black text-[#3B2118] text-xs leading-tight line-clamp-2">
                  {propertyTitle}
                </p>
                <p className="text-[11px] font-semibold text-[#059669] mt-1">
                  {displayDestName}
                </p>
                {propertyPrice && (
                  <p className="text-xs font-black text-[#D84420] mt-1">
                    {formatPrice(propertyPrice)}/mes
                  </p>
                )}
              </div>
            </Popup>
          </Marker>

          {/* Real-time Moving Traveler Marker */}
          {isNavigating && (
            <Marker
              position={smoothVehiclePos}
              icon={createTravelerIcon(currentBearing)}
            >
              <Popup>
                <div className="p-2 text-center font-sans">
                  <p className="font-black text-[#059669] text-xs flex items-center justify-center gap-1.5">
                    <Navigation size={12} className="text-[#059669]" />
                    <span>En Recorrido</span>
                  </p>
                  <p className="text-[10px] text-gray-500">Navegación en tiempo real</p>
                  <p className="text-[10px] font-bold text-[#F59E0B] mt-1">{progressPercent}% del trayecto</p>
                </div>
              </Popup>
            </Marker>
          )}
        </MapContainer>
      )}

      {/* ── ARRIVAL CELEBRATION MODAL ── */}
      {hasReachedDestination && (
        <div className="absolute top-24 left-1/2 -translate-x-1/2 z-40 w-[92%] max-w-md animate-fade-in pointer-events-auto">
          <div
            className="p-5 rounded-2xl text-center text-white shadow-2xl border"
            style={{
              background: 'linear-gradient(135deg, rgba(6, 78, 59, 0.98), rgba(4, 120, 87, 0.96))',
              borderColor: 'rgba(52, 211, 153, 0.6)',
              boxShadow: '0 20px 50px rgba(4, 40, 28, 0.45)',
            }}
          >
            <div className="w-14 h-14 mx-auto mb-2 rounded-2xl bg-white/15 flex items-center justify-center shadow-inner">
              <CheckCircle2 size={34} className="text-[#34D399]" />
            </div>
            <span className="inline-block text-[10px] font-black uppercase tracking-wider bg-[#F59E0B] text-slate-950 px-2.5 py-0.5 rounded-full mb-1">
              Destino Alcanzado
            </span>
            <h3 className="font-black text-lg text-white">¡Has llegado a tu destino!</h3>
            <p className="text-xs font-semibold text-emerald-100 mt-1">{displayDestName}</p>
            <button
              onClick={() => setHasReachedDestination(false)}
              className="mt-3 px-5 py-2 rounded-xl bg-white text-[#0B5D3B] font-black text-xs hover:bg-emerald-50 shadow-md transition-all active:scale-95"
            >
              Entendido
            </button>
          </div>
        </div>
      )}

      {/* ── STEP-BY-STEP MANEUVER DRAWER ── */}
      {showStepDrawer && (
        <div
          className="absolute top-44 right-4 w-80 max-h-[360px] rounded-2xl p-4 text-white z-30 flex flex-col"
          style={{
            background: 'linear-gradient(135deg, rgba(15, 23, 42, 0.97) 0%, rgba(15, 23, 42, 0.93) 100%)',
            backdropFilter: 'blur(20px)',
            border: '1px solid rgba(212, 150, 42, 0.35)',
            boxShadow: '0 12px 40px rgba(0,0,0,0.4)',
          }}
        >
          <div className="flex items-center justify-between border-b border-white/10 pb-2 mb-3">
            <div>
              <h4 className="font-black text-sm text-[#FFF5E8] flex items-center gap-1.5">
                <Layers size={16} className="text-[#D4962A]" />
                Pasos de la Ruta
              </h4>
              <p className="text-[10px] text-[#10B981] font-bold mt-0.5">
                Trazado por calles reales
              </p>
            </div>
            <button
              onClick={() => setShowStepDrawer(false)}
              className="p-1.5 rounded-lg bg-white/10 hover:bg-white/20 text-white/70 hover:text-white transition-colors"
            >
              <X size={14} />
            </button>
          </div>
          
          <div className="overflow-y-auto space-y-1.5 pr-1 flex-1 text-xs">
            {steps.map((st, i) => (
              <button
                key={i}
                onClick={() => {
                  if (st.location) setTargetFocus(st.location);
                  setSelectedStepIndex(i);
                  speakAssistant(st.instruction);
                }}
                className={`w-full text-left p-2.5 rounded-xl border transition-all flex items-start gap-2.5 ${
                  selectedStepIndex === i
                    ? 'bg-[#0B5D3B]/60 border-[#D4962A]/60 text-white shadow-md'
                    : 'bg-white/5 border-white/5 text-white/75 hover:bg-white/10 hover:border-white/15'
                }`}
              >
                <span
                  className="w-6 h-6 rounded-full text-white text-[10px] font-black flex items-center justify-center shrink-0 mt-0.5"
                  style={{
                    background: selectedStepIndex === i
                      ? 'linear-gradient(135deg, #D84420, #F07824)'
                      : 'rgba(216, 68, 32, 0.5)',
                  }}
                >
                  {i + 1}
                </span>
                <div className="flex-1 min-w-0">
                  <p className="font-bold leading-snug">{st.instruction}</p>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[10px] text-[#D4962A] font-extrabold bg-[#D4962A]/10 px-1.5 py-0.5 rounded">
                      {st.streetName}
                    </span>
                    <span className="text-[10px] text-white/50">
                      {Math.round(st.distance || 100)}m
                    </span>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── BOTTOM RUWAJAY PREMIUM DASHBOARD HUD ── */}
      <div className="absolute bottom-0 left-0 right-0 z-20">
        <div
          className="m-3 p-3.5 sm:px-4 sm:py-3 rounded-[22px]"
          style={{
            background: 'linear-gradient(135deg, rgba(6, 78, 59, 0.96) 0%, rgba(4, 120, 87, 0.92) 50%, rgba(6, 95, 70, 0.96) 100%)',
            backdropFilter: 'blur(20px)',
            border: '1px solid rgba(52, 211, 153, 0.3)',
            boxShadow: '0 16px 42px rgba(4, 40, 28, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.16)',
          }}
        >
          <div className="flex flex-wrap items-center justify-between gap-3">
            
            {/* Estimated Time, Distance & Street Summary with Real-World Factors */}
            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2.5 sm:gap-4">
              <div className="flex items-center gap-3">
                <div className="flex items-baseline gap-1">
                  <span
                    className="text-3xl sm:text-4xl font-black tracking-tight"
                    style={{ color: '#F2B544' }}
                  >
                    {durationMins}
                  </span>
                  <span className="text-xs font-bold text-white/70">min</span>
                </div>
                
                <div className="h-10 w-px bg-white/15 rounded-full" />
                
                <div>
                  <span className="text-xs sm:text-sm font-black text-white block">
                    {distanceKm} km
                    <span className="text-[#34D399] font-extrabold text-[10px] ml-1.5 bg-[#34D399]/20 px-1.5 py-0.5 rounded border border-[#34D399]/30">
                      Ruta más corta
                    </span>
                  </span>
                  <span className="text-[10px] font-bold text-[#FFF5E8]/70 truncate block max-w-[200px]">
                    {routeSummary}
                  </span>
                </div>
              </div>

              {/* Real-World Pills: Tráfico, Lluvia, Obstáculos (SVG Icons) */}
              {currentRoute?.realWorld && (
                <div className="flex flex-wrap items-center gap-1.5 text-[10px] font-extrabold">
                  <span className="inline-flex items-center gap-1.5 rounded-lg bg-black/20 backdrop-blur-md px-2.5 py-1 text-amber-300 border border-amber-400/25 shadow-sm" title={currentRoute.realWorld.trafficLabel}>
                    <Car size={13} className="text-amber-300 shrink-0" />
                    <span>+{currentRoute.realWorld.trafficDelayMins}m tráfico</span>
                  </span>
                  <span className="inline-flex items-center gap-1.5 rounded-lg bg-black/20 backdrop-blur-md px-2.5 py-1 text-sky-300 border border-sky-400/25 shadow-sm" title={currentRoute.realWorld.rainLabel}>
                    <CloudRain size={13} className="text-sky-300 shrink-0" />
                    <span>+{currentRoute.realWorld.rainDelayMins}m {currentRoute.realWorld.isRainHours ? 'lluvia' : 'clima'}</span>
                  </span>
                  <span className="inline-flex items-center gap-1.5 rounded-lg bg-black/20 backdrop-blur-md px-2.5 py-1 text-orange-300 border border-orange-400/25 shadow-sm" title={currentRoute.realWorld.obstacleLabel}>
                    <AlertTriangle size={13} className="text-orange-300 shrink-0" />
                    <span>+{currentRoute.realWorld.obstacleDelayMins}m obstáculos</span>
                  </span>
                  {currentRoute.realWorld.hasIncident && (
                    <span className="inline-flex items-center gap-1.5 rounded-lg bg-red-500/25 backdrop-blur-md px-2.5 py-1 text-red-200 border border-red-500/35 shadow-sm">
                      <AlertOctagon size={13} className="text-red-300 shrink-0" />
                      <span>Choque/cierre</span>
                    </span>
                  )}
                </div>
              )}
            </div>

            {/* Camera Auto-follow Toggle */}
            {isNavigating && (
              <button
                onClick={() => setFollowVehicle(!followVehicle)}
                className={`flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold transition-all border ${
                  followVehicle
                    ? 'bg-[#10B981] text-slate-950 border-[#10B981] shadow-md shadow-[#10B981]/30'
                    : 'bg-white/10 text-white border-white/20 hover:bg-white/15'
                }`}
                title="Cámara siguiendo al vehículo"
              >
                <Camera size={14} />
                <span>{followVehicle ? 'Siguiendo' : 'Seguir'}</span>
              </button>
            )}

            {/* Navigation & Controls */}
            <div className="flex items-center gap-2">
              {/* Speed Selector (Available in desktop preview mode) */}
              {isNavigating && !isTracking && (
                <button
                  onClick={() => setSimSpeed((prev) => (prev === 1 ? 2 : prev === 2 ? 4 : 1))}
                  className="px-2.5 py-1.5 rounded-xl text-[11px] font-extrabold text-[#D4962A] border border-white/10 hover:bg-white/10 transition-all"
                  style={{ background: 'rgba(255,255,255,0.08)' }}
                  title="Velocidad de simulación"
                >
                  {simSpeed}x
                </button>
              )}

              {/* Iniciar / Pausar Recorrido en Tiempo Real */}
              <button
                onClick={handleToggleNavigation}
                className={`flex items-center gap-1.5 px-4 py-2.5 rounded-xl text-white font-black text-xs transition-all active:scale-[.98] ${
                  isNavigating
                    ? 'bg-[#0B5D3B] hover:bg-[#09482E]'
                    : 'bg-[#D84420] hover:bg-[#C93D1C]'
                }`}
                style={{
                  boxShadow: isNavigating ? '0 7px 18px rgba(11,93,59,.35)' : '0 7px 18px rgba(216,68,32,.28)',
                  border: '1px solid rgba(255,255,255,0.2)',
                }}
              >
                {isNavigating ? <Pause size={14} /> : <Play size={14} />}
                <span>{isNavigating ? 'Pausar Recorrido' : 'Iniciar Recorrido'}</span>
              </button>

              {/* Reset Recorrido */}
              <button
                onClick={handleResetNavigation}
                className="p-2.5 rounded-xl bg-white/10 hover:bg-white/15 text-white transition-colors border border-white/10"
                title="Reiniciar recorrido"
              >
                <RotateCcw size={15} />
              </button>

              {/* Recenter Route */}
              <button
                onClick={handleRecenterRoute}
                className="p-2.5 rounded-xl bg-white/10 hover:bg-white/15 text-white transition-colors border border-white/10"
                title="Centrar ruta completa"
              >
                <Compass size={15} />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* ── RUWAJAY OFFICIAL WATERMARK BADGE ── */}
      <div
        className="absolute bottom-24 left-4 z-10 pointer-events-none hidden md:flex items-center gap-2 px-3.5 py-1.5 rounded-full text-[10px] font-bold"
        style={{
          background: 'linear-gradient(135deg, rgba(6, 78, 59, 0.95) 0%, rgba(4, 120, 87, 0.90) 100%)',
          backdropFilter: 'blur(14px)',
          border: '1px solid rgba(52, 211, 153, 0.35)',
          color: '#FFF5E8',
          boxShadow: '0 6px 20px rgba(6, 78, 59, 0.3)',
        }}
      >
        <ShieldCheck size={14} className="text-[#34D399]" />
        <span>RuwaJay Maps · Navegación Oficial</span>
        {isTracking && (
          <span className="inline-flex items-center gap-1 text-[#34D399] font-black ml-1">
            <Radio size={11} className="animate-pulse" /> GPS
          </span>
        )}
      </div>

      {/* Loading overlay */}
      {loading && (
        <div className="absolute inset-0 z-30 flex items-center justify-center bg-[#0F172A]/80 backdrop-blur-sm">
          <div className="flex flex-col items-center gap-4">
            <div className="relative">
              <div className="w-16 h-16 border-4 border-[#0B5D3B]/30 rounded-full" />
              <div className="absolute inset-0 w-16 h-16 border-4 border-t-[#D4962A] border-r-transparent border-b-transparent border-l-transparent rounded-full animate-spin" />
            </div>
            <div className="text-center">
              <p className="text-white font-black text-sm">Calculando ruta óptima...</p>
              <p className="text-white/50 text-xs mt-1">RuwaJay Maps</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { doc, setDoc, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { firestore } from '../../lib/firebase';
import { subscribeToUserVisits } from '../../lib/visitService';
import { getOrCreateConversation } from '../../lib/chatService';
import { X, Printer, Copy, Check, FileText, ShieldCheck, Scale, Calendar, User, Home, Download } from 'lucide-react';
import { formatPrice } from '../../data/properties';

/**
 * LeaseContractModal — Official residential lease agreement generator for Guatemala
 * Conforms to Articles 1880 to 1941 of the Guatemalan Civil Code (Decreto Ley 106).
 * Features:
 * - Pre-filled fields from property and user (including verified DPI if available)
 * - Live preview of legal document
 * - Print-ready layout (@media print) for direct PDF export
 * - Copy text capability
 */
export default function LeaseContractModal({
  isOpen,
  onClose,
  property,
  owner,
  user,
}) {
  const [activeTab, setActiveTab] = useState('preview'); // 'preview' | 'edit'
  const [copied, setCopied] = useState(false);
  const [visits,setVisits] = useState([]);
  const [selectedVisit,setSelectedVisit] = useState('');
  const [room,setRoom] = useState(null);
  const [saveStatus,setSaveStatus] = useState('');

  // Extract user verified DPI if available
  const userCui = user?.dpiData?.cui || '';
  const userAddress = user?.dpiData?.legalAddress || '';

  // Form states
  const [contractData, setContractData] = useState({
    city: property?.address?.municipality || '',
    day: new Date().getDate(),
    month: new Date().toLocaleString('es-GT', { month: 'long' }),
    year: new Date().getFullYear(),
    ownerName: owner?.name || property?.ownerName || '',
    ownerCui: '',
    ownerAddress: owner?.legalAddress || '',
    tenantName: user?.name || 'Inquilino Arrendatario',
    tenantCui: userCui || '',
    tenantAddress: userAddress,
    hasGuarantor: false,
    guarantorName: 'Fiador Mancomunado',
    guarantorCui: '',
    propertyAddress: property?.address?.exact || property?.address?.approximate || '',
    propertyDepartment: property?.address?.department || '',
    monthlyRent: property?.price || 0,
    depositAmount: property?.deposit ?? property?.price ?? 0,
    maintenanceFee: Number(property?.maintenanceFee) || 0,
    durationMonths: 12,
    startDate: new Date().toISOString().split('T')[0],
  });

  useEffect(()=>subscribeToUserVisits(user?.id,items=>setVisits(items.filter(v=>v.propertyId===property?.id && ['confirmada','aceptada'].includes(v.status)))),[user?.id,property?.id]);
  const visit=visits.find(v=>v.id===selectedVisit)||visits[0];
  useEffect(()=>{
    setRoom(null);
    if(!isOpen||!visit) return;
    let active=true,unsubscribe=()=>{};
    getOrCreateConversation(visit.tenantId,visit.ownerId,visit.propertyId).then(id=>{
      if(!active)return;
      setRoom({id,participants:[visit.tenantId,visit.ownerId],ownerId:visit.ownerId});
      setContractData(previous=>({...previous,ownerName:visit.ownerName,tenantName:visit.tenantName}));
      unsubscribe=onSnapshot(doc(firestore,'lease_drafts',id),snapshot=>{
        if(snapshot.exists())setContractData(previous=>({...previous,...snapshot.data().terms}));
      },error=>setSaveStatus(error.message));
    }).catch(error=>{if(active)setSaveStatus(error.message);});
    return()=>{active=false;unsubscribe();};
  },[isOpen,visit?.id]);
  const saveDraft=async()=>{
    try {
      const terms={...contractData,monthlyRent:Number(contractData.monthlyRent),depositAmount:Number(contractData.depositAmount),
        maintenanceFee:Number(contractData.maintenanceFee),durationMonths:Number(contractData.durationMonths)};
      await setDoc(doc(firestore,'lease_drafts',room.id),{participants:room.participants,conversationId:room.id,
        ownerId:room.ownerId,propertyId:property.id,terms,updatedAt:serverTimestamp()});
      setSaveStatus('Borrador guardado y compartido con el interesado.');
    }catch(error){setSaveStatus(error.message||'No se pudo guardar el borrador.');}
  };

  const handlePrint = () => {
    window.print();
  };

  const handleCopy = () => {
    const el = document.getElementById('printable-contract-text');
    if (el) {
      navigator.clipboard.writeText(el.innerText);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    }
  };

  if (!isOpen || !property) return null;
  const signingDate = new Date(`${contractData.startDate || new Date().toISOString().slice(0,10)}T12:00:00-06:00`);

  return (
    <div className="fixed inset-0 z-[85] flex items-center justify-center overflow-y-auto bg-black/60 p-2 sm:p-4 backdrop-blur-sm animate-[fade-in_0.2s_ease-out]">
      <div className="flex max-h-[92vh] w-full max-w-4xl flex-col rounded-3xl bg-white shadow-2xl overflow-hidden border border-border">
        <div className="p-4 border-b print:hidden">
          <p className="text-sm">Borrador sin firma. Las condiciones guardadas se comparten entre web y app.</p>
          {visits.length>1 && <select value={visit?.id || ''} onChange={event=>setSelectedVisit(event.target.value)} className="p-2 border rounded">
            {visits.map(v=><option key={v.id} value={v.id}>{v.tenantName} - {v.date}</option>)}
          </select>}
          {room?.ownerId===user?.id && <button onClick={saveDraft} className="p-2 rounded bg-forest text-white">Guardar borrador compartido</button>}
          {!visit && <p className="text-xs">Para compartir el borrador necesitas una visita confirmada.</p>}
          {saveStatus && <p role="status" className="text-sm">{saveStatus}</p>}
        </div>
        {/* Header (Hidden on print) */}
        <div className="flex items-center justify-between border-b border-border bg-[#FDFBF7] px-5 py-4 print:hidden">
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-forest text-white shadow-sm">
              <Scale size={22} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h3 className="text-base font-black text-cafe sm:text-lg">
                  Borrador de Contrato de Arrendamiento
                </h3>
                <span className="inline-flex items-center gap-1 rounded-full bg-forest/10 px-2 py-0.5 text-[10px] font-extrabold text-forest border border-forest/20">
                  <ShieldCheck size={11} /> Leyes de Guatemala
                </span>
              </div>
              <p className="text-xs text-text-muted">
                Código Civil de Guatemala (Decreto Ley 106, Art. 1880 - 1941)
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handlePrint}
              className="flex min-h-10 items-center gap-1.5 rounded-xl bg-forest px-3.5 py-2 text-xs font-black text-white hover:bg-forest-dark transition-all shadow-xs active:scale-95"
            >
              <Printer size={15} />
              <span className="hidden sm:inline">Imprimir / PDF</span>
            </button>

            <button
              type="button"
              onClick={handleCopy}
              className="flex min-h-10 items-center gap-1.5 rounded-xl border border-border bg-white px-3.5 py-2 text-xs font-bold text-cafe hover:bg-crema transition-all"
            >
              {copied ? <Check size={15} className="text-forest" /> : <Copy size={15} />}
              <span className="hidden sm:inline">{copied ? 'Copiado' : 'Copiar'}</span>
            </button>

            <button
              type="button"
              onClick={onClose}
              className="flex h-10 w-10 items-center justify-center rounded-full text-text-muted hover:bg-cafe/5 hover:text-cafe transition-colors"
              aria-label="Cerrar"
            >
              <X size={20} />
            </button>
          </div>
        </div>

        {/* View Switcher (Hidden on print) */}
        <div className="flex items-center justify-between border-b border-border bg-crema/40 px-6 py-2.5 print:hidden">
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => setActiveTab('preview')}
              className={`rounded-xl px-3 py-1.5 text-xs font-bold transition-all ${
                activeTab === 'preview'
                  ? 'bg-forest text-white shadow-xs'
                  : 'text-cafe hover:bg-white'
              }`}
            >
              Vista Previa Legal
            </button>
            <button
              type="button"
              onClick={() => setActiveTab('edit')}
              className={`rounded-xl px-3 py-1.5 text-xs font-bold transition-all ${
                activeTab === 'edit'
                  ? 'bg-forest text-white shadow-xs'
                  : 'text-cafe hover:bg-white'
              }`}
            >
              Editar Datos del Contrato
            </button>
          </div>

          <span className="text-[11px] font-semibold text-text-muted hidden sm:inline">
            Propiedad: <strong className="text-cafe">{property.title}</strong>
          </span>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto p-5 sm:p-8 bg-[#FAF8F5]">
          {/* EDIT FORM TAB */}
          {activeTab === 'edit' && (
            <div className="space-y-6 max-w-2xl mx-auto print:hidden bg-white p-6 rounded-2xl border border-border shadow-xs">
              <h4 className="font-extrabold text-cafe text-sm uppercase tracking-wider border-b border-border/60 pb-2">
                Partes Comparecientes
              </h4>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">Nombre del Arrendante (Propietario)</label>
                  <input
                    type="text"
                    value={contractData.ownerName}
                    onChange={(e) => setContractData({ ...contractData, ownerName: e.target.value })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">DPI / CUI del Arrendante</label>
                  <input
                    type="text"
                    value={contractData.ownerCui}
                    onChange={(e) => setContractData({ ...contractData, ownerCui: e.target.value })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">Nombre del Arrendatario (Inquilino)</label>
                  <input
                    type="text"
                    value={contractData.tenantName}
                    onChange={(e) => setContractData({ ...contractData, tenantName: e.target.value })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">DPI / CUI del Arrendatario</label>
                  <input
                    type="text"
                    value={contractData.tenantCui}
                    onChange={(e) => setContractData({ ...contractData, tenantCui: e.target.value })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>
              </div>

              <h4 className="font-extrabold text-cafe text-sm uppercase tracking-wider border-b border-border/60 pb-2 pt-2">
                Condiciones del Alquiler (Quetzales)
              </h4>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">Renta Mensual (Q)</label>
                  <input
                    type="number"
                    value={contractData.monthlyRent}
                    onChange={(e) => setContractData({ ...contractData, monthlyRent: Number(e.target.value) })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">Depósito en Garantía (Q)</label>
                  <input
                    type="number"
                    value={contractData.depositAmount}
                    onChange={(e) => setContractData({ ...contractData, depositAmount: Number(e.target.value) })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-cafe mb-1">Cuota Garita / Mant. (Q)</label>
                  <input
                    type="number"
                    value={contractData.maintenanceFee}
                    onChange={(e) => setContractData({ ...contractData, maintenanceFee: Number(e.target.value) })}
                    className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-cafe mb-1">Dirección del Inmueble</label>
                <input
                  type="text"
                  value={contractData.propertyAddress}
                  onChange={(e) => setContractData({ ...contractData, propertyAddress: e.target.value })}
                  className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3 py-2 text-xs font-semibold text-cafe outline-none focus:border-forest"
                />
              </div>

              <div className="flex justify-end pt-3">
                <button
                  type="button"
                  onClick={() => setActiveTab('preview')}
                  className="rounded-xl bg-forest px-5 py-2 text-xs font-black text-white hover:bg-forest-dark"
                >
                  Actualizar y Ver Contrato
                </button>
              </div>
            </div>
          )}

          {/* LEGAL DOCUMENT PREVIEW (Printable) */}
          <div
            id="printable-contract-text"
            className="max-w-3xl mx-auto bg-white p-8 sm:p-12 rounded-2xl border border-border shadow-md print:shadow-none print:border-none print:p-0 text-cafe font-serif leading-relaxed text-sm print:text-black"
          >
            {/* Watermark/Emblem */}
            <div className="text-center border-b-2 border-forest/20 pb-5 mb-6">
              <p className="text-[10px] font-sans font-black uppercase tracking-[0.25em] text-dorado mb-1">
                República de Guatemala • Documento Privado con Legalización de Firmas
              </p>
              <h2 className="text-lg sm:text-xl font-black font-sans uppercase tracking-tight text-cafe">
                CONTRATO PRIVADO DE ARRENDAMIENTO DE BIEN INMUEBLE PARA VIVIENDA
              </h2>
              <p className="text-[11px] font-sans text-text-muted mt-1">
                Fundamento Legal: Artículos 1880 al 1941 del Código Civil de Guatemala (Decreto Ley 106)
              </p>
            </div>

            {/* Introductory clause */}
            <p className="mb-4 text-justify">
              En la ciudad de <strong>{(property.address?.municipality || property.location?.municipality || 'Por completar')}</strong>, departamento de <strong>{contractData.propertyDepartment}</strong>,
              el día <strong>{signingDate.getDate()}</strong> de <strong>{signingDate.toLocaleDateString('es-GT',{month:'long'})}</strong> del año <strong>{signingDate.getFullYear()}</strong>,
              comparecemos por una parte: <strong>{contractData.ownerName}</strong>, mayor de edad, con domicilio en {contractData.ownerAddress},
              quien se identifica con el Código Único de Identificación —CUI— del Documento Personal de Identificación —DPI— número{' '}
              <strong>{contractData.ownerCui}</strong>, extendido por el Registro Nacional de las Personas —RENAP— de la República de Guatemala,
              a quien en lo sucesivo de este instrumento se le denominará simplemente como <strong>"EL ARRENDANTE"</strong>; y por la otra parte:{' '}
              <strong>{contractData.tenantName}</strong>, mayor de edad, con domicilio en {contractData.tenantAddress}, quien se identifica con el
              Código Único de Identificación —CUI— del Documento Personal de Identificación —DPI— número{' '}
              <strong>{contractData.tenantCui}</strong>, extendido por el RENAP, a quien en adelante se le denominará{' '}
              <strong>"EL ARRENDATARIO"</strong>. Ambos otorgantes manifestamos encontrarnos en el libre ejercicio de nuestros derechos civiles y
              convenir en celebrar el presente <strong>CONTRATO DE ARRENDAMIENTO RESIDENCIAL</strong>, sujeto a las cláusulas siguientes:
            </p>

            {/* CLAUSES */}
            <div className="space-y-4 text-justify">
              <p>
                <strong>PRIMERA: DEL INMUEBLE OBJETO DEL CONTRATO.</strong> Manifiesta EL ARRENDANTE que es legítimo poseedor del bien inmueble
                ubicado en: <strong>{contractData.propertyAddress}</strong>, departamento de {contractData.propertyDepartment}. El inmueble cuenta
                con sus instalaciones completas, servicios de agua potable, servicio sanitario, energía eléctrica y accesorios en perfecto estado de
                funcionamiento y conservación, comprometiéndose EL ARRENDATARIO a entregarlo al vencimiento en el mismo estado en que hoy lo recibe.
              </p>

              <p>
                <strong>SEGUNDA: DEL PLAZO Y VIGENCIA.</strong> El plazo del presente arrendamiento será de{' '}
                <strong>{contractData.durationMonths} MESES FORZOSOS</strong>, contados a partir de la fecha de inicio convenida ({contractData.startDate}).
                Dicho plazo podrá prorrogarse únicamente mediante cruce de cartas escritas o firma de nuevo documento con al menos treinta (30) días
                calendario de anticipación a su vencimiento.
              </p>

              <p>
                <strong>TERCERA: DEL PRECIO DE LA RENTA Y FORMA DE PAGO.</strong> EL ARRENDATARIO se obliga formalmente a pagar a EL ARRENDANTE en
                concepto de renta mensual la suma de <strong>{formatPrice(contractData.monthlyRent)} EXACTOS</strong> mensuales anticipados, los
                cuales deberán hacerse efectivos dentro de los <strong>primeros cinco (5) días calendario</strong> de cada mes, mediante depósito o
                transferencia bancaria a la cuenta designada por EL ARRENDANTE. La falta de pago puntual causará un recargo moratorio mensual por retraso
                además de constituir causa inmediata de resolución del contrato.
              </p>

              <p>
                <strong>CUARTA: DEL DEPÓSITO EN GARANTÍA.</strong> En este acto EL ARRENDATARIO entrega a EL ARRENDANTE la cantidad de{' '}
                <strong>{formatPrice(contractData.depositAmount)} EXACTOS</strong> en concepto de depósito de garantía. Dicha suma garantizará el pago
                de cualquier daño atribuible al inquilino, reparaciones locativas o saldos pendientes de servicios públicos. Este depósito en ningún caso
                podrá abonarse como pago de mensualidad de renta y será devuelto dentro de los treinta (30) días posteriores a la desocupación formal del
                inmueble previa verificación del finiquito de servicios.
              </p>

              <p>
                <strong>QUINTA: DESTINO EXCLUSIVO Y PROHIBICIONES.</strong> El inmueble se destinará única y exclusivamente para{' '}
                <strong>HABITACIÓN Y VIVIENDA FAMILIAR</strong>. Queda terminantemente prohibido a EL ARRENDATARIO: a) Subarrendar total o parcialmente el
                bien inmueble a terceras personas naturales o jurídicas; b) Introducir sustancias inflamables, corrosivas o explosivas; c) Destinar el
                inmueble para actividades mercantiles abiertas al público, ilícitas o reñidas con la moral; d) Modificar la estructura arquitectónica del
                inmueble sin previa autorización expresa y por escrito de EL ARRENDANTE.
              </p>

              <p>
                <strong>SEXTA: DE LOS SERVICIOS Y MANTENIMIENTO.</strong> Correrá por cuenta exclusiva de EL ARRENDATARIO el pago puntual de su consumo
                de energía eléctrica, servicio de internet/cable y la cuota mensual de seguridad/garita de <strong>{formatPrice(contractData.maintenanceFee)}</strong>.
                Las reparaciones locativas originadas por el uso ordinario o negligencia del inquilino serán cubiertas por este último.
              </p>

              <p>
                <strong>SÉPTIMA: DE LA TERMINACIÓN ANTICIPADA Y DESAHUCIO.</strong> Son causas de terminación anticipada de pleno derecho: el vencimiento
                del plazo, la falta de pago de una sola mensualidad de renta en el tiempo estipulado, la violación a cualquiera de las prohibiciones pactadas
                o el deterioro grave de la propiedad. EL ARRENDATARIO renuncia expresamente al fuero de su domicilio y se somete a los Tribunales de
                Justicia del departamento de {contractData.propertyDepartment}, aceptando como buenas y exactas las cuentas que formule EL ARRENDANTE y como
                líquido y exigible el saldo que se le reclame.
              </p>

              <p>
                <strong>OCTAVA: ACEPTACIÓN FORMAL.</strong> En los términos consignados, las partes comparecientes leemos íntegramente lo estipulado en este
                documento privado, y enterados de su contenido, validez y efectos legales, lo ratificamos, aceptamos y firmamos de mutuo acuerdo.
              </p>
            </div>

            {/* SIGNATURE SECTION */}
            <div className="grid grid-cols-2 gap-12 pt-16 mt-8 border-t border-border/80">
              <div className="text-center">
                <div className="border-t-2 border-cafe pt-2">
                  <p className="font-bold text-xs">{contractData.ownerName}</p>
                  <p className="text-[11px] text-text-muted">EL ARRENDANTE (Propietario)</p>
                  <p className="text-[10px] text-text-muted">DPI: {contractData.ownerCui}</p>
                </div>
              </div>

              <div className="text-center">
                <div className="border-t-2 border-cafe pt-2">
                  <p className="font-bold text-xs">{contractData.tenantName}</p>
                  <p className="text-[11px] text-text-muted">EL ARRENDATARIO (Inquilino)</p>
                  <p className="text-[10px] text-text-muted">DPI: {contractData.tenantCui}</p>
                </div>
              </div>
            </div>

            {/* Legal stamp note */}
            <div className="mt-12 text-center text-[10px] text-text-muted/80 italic border-t border-dashed border-border pt-3">
              Generado automáticamente a través de la plataforma inmobiliaria RuwaJay Guatemala • Modelo estándar de contrato privado conforme a la legislación vigente.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import {
  Star, MessageSquare, CheckCircle, PlusCircle, Sparkles,
  ThumbsUp, ShieldCheck, UserCheck, ChevronDown, ChevronUp
} from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import { demoReviews } from '../../data/properties';
import { collection, addDoc, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { firebaseAuth, firestore } from '../../lib/firebase';

const QUICK_TAGS = [
  'Zona muy segura',
  'Garita 24/7',
  'Agua constante',
  'Parqueo amplio',
  'Excelente ubicación',
  'Trato amable',
  'Ambiente tranquilo',
  'Buena iluminación',
];

export default function PropertyReviews({ propertyId, propertyTitle }) {
  const { user } = useAuth();
  const [reviews, setReviews] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [userRating, setUserRating] = useState(5);
  const [hoverRating, setHoverRating] = useState(0);
  const [userName, setUserName] = useState(user?.name || '');
  const [comment, setComment] = useState('');
  const [selectedTags, setSelectedTags] = useState(['Zona muy segura', 'Trato amable']);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [successMessage, setSuccessMessage] = useState('');
  const [likedReviews, setLikedReviews] = useState({});
  const apiUrl = (import.meta.env.VITE_API_URL || '').replace(/\/$/, '');

  // Sync user name if logged in
  useEffect(() => {
    if (user?.name && !userName) {
      setUserName(user.name);
    }
  }, [user]);

  useEffect(() => {
    setReviews([]);
    return onSnapshot(collection(firestore,'properties',propertyId,'reviews'), snapshot => {
      setReviews(snapshot.docs.map(d => ({ ...d.data(),id:d.id,
        date:d.data().createdAt?.toDate?.().toLocaleDateString('es-GT') || '' })));
    }, error => setSuccessMessage(error.message));
  }, [propertyId]);

  // Calculate statistics
  const stats = useMemo(() => {
    if (!reviews.length) return { average: 5.0, count: 0 };
    const sum = reviews.reduce((acc, r) => acc + (Number(r.rating) || 5), 0);
    const avg = sum / reviews.length;
    return {
      average: avg.toFixed(1),
      count: reviews.length,
    };
  }, [reviews]);

  const handleToggleTag = (tag) => {
    setSelectedTags((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
  };

  const handleLikeReview = (reviewId) => {
    setLikedReviews((prev) => ({
      ...prev,
      [reviewId]: !prev[reviewId],
    }));
  };

  const handleSubmitReview = async (e) => {
    e.preventDefault();
    if (!comment.trim()) return;

    setIsSubmitting(true);

    const newReview = {
      id: `rev-${Date.now()}`,
      userName: userName.trim() || 'Inquilino de RuwaJay',
      userAvatar: user?.avatarImage || null,
      rating: userRating,
      date: new Date().toLocaleDateString('es-GT', { year: 'numeric', month: 'long', day: 'numeric' }),
      verifiedTenant: !!user?.verified,
      comment: comment.trim(),
      tags: selectedTags,
      isNew: true,
    };

    try {
      if (!firebaseAuth?.currentUser) throw new Error('Debes iniciar sesion para publicar una resena.');
      await addDoc(collection(firestore,'properties',propertyId,'reviews'),{
        ...newReview,userId:firebaseAuth.currentUser.uid,verifiedTenant:false,createdAt:serverTimestamp(),
      });
      setShowAddModal(false); setComment(''); setSuccessMessage('Tu opinion se ha guardado.');
    } catch (error) { setSuccessMessage(error.message || 'No se pudo guardar tu opinion.'); }
    finally { setIsSubmitting(false); }
  };

  return (
    <section className="mt-10 rounded-3xl border border-border-light bg-white p-5 shadow-card sm:p-8">
      {/* Section Header */}
      <div className="flex flex-col gap-4 border-b border-border-light pb-6 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="flex items-center gap-2.5">
            <div className="w-10 h-10 rounded-2xl bg-dorado/15 text-dorado flex items-center justify-center shadow-xs">
              <Star size={20} fill="currentColor" />
            </div>
            <div>
              <h3 className="text-xl font-black text-cafe sm:text-2xl">
                Opiniones y Reseñas
              </h3>
              <p className="text-xs text-text-muted font-medium">
                Experiencias de inquilinos que han visitado o vivido en esta propiedad
              </p>
            </div>
          </div>
        </div>

        <button
          type="button"
          onClick={() => setShowAddModal(!showAddModal)}
          className="btn-primary flex items-center justify-center gap-2 !rounded-2xl !py-3 !px-5 text-xs sm:text-sm shadow-md"
        >
          <PlusCircle size={16} />
          {showAddModal ? 'Cancelar reseña' : 'Escribir una opinión'}
        </button>
      </div>

      {/* Success Notification */}
      {successMessage && (
        <div className="mt-4 flex items-center gap-2.5 rounded-2xl bg-jade/10 p-4 text-xs font-bold text-jade border border-jade/20 animate-[fade-in_0.2s_ease-out]">
          <CheckCircle size={17} className="flex-shrink-0" />
          <span>{successMessage}</span>
        </div>
      )}

      {/* Score Summary & Categories */}
      <div className="mt-6 grid grid-cols-1 gap-6 rounded-2xl bg-[#FAF5EE]/70 p-5 sm:grid-cols-12 sm:items-center">
        {/* Overall Score */}
        <div className="sm:col-span-4 text-center sm:border-r sm:border-border-light sm:pr-6">
          <div className="text-4xl sm:text-5xl font-black text-cafe">
            {stats.average}
          </div>
          <div className="mt-1 flex items-center justify-center gap-1 text-dorado">
            {[1, 2, 3, 4, 5].map((star) => (
              <Star
                key={star}
                size={18}
                fill={star <= Math.round(stats.average) ? 'currentColor' : 'none'}
              />
            ))}
          </div>
          <p className="mt-1 text-xs font-extrabold text-text-muted">
            Basado en {stats.count} {stats.count === 1 ? 'opinión' : 'opiniones'} verificadas
          </p>
        </div>

        {/* Category breakdown */}
        <div className="sm:col-span-8 space-y-2.5 text-xs font-bold text-cafe">
          {[
            { label: 'Limpieza y estado del inmueble', score: '98%', val: 4.9 },
            { label: 'Seguridad y tranquilidad del sector', score: '96%', val: 4.8 },
            { label: 'Comunicación y atención del arrendador', score: '97%', val: 4.9 },
            { label: 'Relación calidad / precio mensual', score: '94%', val: 4.7 },
          ].map((cat) => (
            <div key={cat.label} className="flex items-center gap-3">
              <span className="w-48 text-[11px] text-text-secondary truncate">{cat.label}</span>
              <div className="flex-1 h-2 rounded-full bg-[#E8D9C8] overflow-hidden">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-forest to-jade"
                  style={{ width: cat.score }}
                />
              </div>
              <span className="w-8 text-right text-[11px] font-black text-forest">{cat.val}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Form: Add Review */}
      {showAddModal && (
        <form
          onSubmit={handleSubmitReview}
          className="mt-6 rounded-3xl border-2 border-forest/15 bg-white p-5 sm:p-7 shadow-lg space-y-4 animate-[scale-up_0.2s_ease-out]"
        >
          <div className="flex items-center justify-between border-b border-border-light pb-3">
            <h4 className="text-sm font-black text-cafe flex items-center gap-2">
              <Sparkles size={16} className="text-dorado" />
              Comparte tu experiencia con esta vivienda
            </h4>
            <span className="text-[11px] text-text-muted font-bold">
              {user ? `Opinando como ${user.name}` : 'Opinión pública'}
            </span>
          </div>

          {/* Star selector */}
          <div>
            <label className="mb-1.5 block text-xs font-extrabold uppercase tracking-wider text-cafe">
              Tu Calificación General *
            </label>
            <div className="flex items-center gap-2">
              <div className="flex items-center gap-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <button
                    key={s}
                    type="button"
                    onMouseEnter={() => setHoverRating(s)}
                    onMouseLeave={() => setHoverRating(0)}
                    onClick={() => setUserRating(s)}
                    className="p-1 text-dorado transition-transform hover:scale-115 focus:outline-none"
                    aria-label={`Calificar con ${s} estrellas`}
                  >
                    <Star
                      size={24}
                      fill={(hoverRating || userRating) >= s ? 'currentColor' : 'none'}
                    />
                  </button>
                ))}
              </div>
              <span className="text-xs font-black text-dorado ml-2">
                {userRating === 5 && '¡Excelente experiencia!'}
                {userRating === 4 && 'Muy buena propiedad'}
                {userRating === 3 && 'Buena opción'}
                {userRating === 2 && 'Regular'}
                {userRating === 1 && 'Necesita mejorar'}
              </span>
            </div>
          </div>

          {/* User Name input if not logged in */}
          {!user && (
            <div>
              <label className="mb-1 block text-xs font-extrabold uppercase tracking-wider text-cafe">
                Tu nombre *
              </label>
              <input
                type="text"
                required
                value={userName}
                onChange={(e) => setUserName(e.target.value)}
                placeholder="Ej. Juan Pérez"
                className="w-full rounded-xl border border-border bg-[#FDFBF7] px-3.5 py-2.5 text-xs font-bold text-cafe outline-none focus:border-forest"
              />
            </div>
          )}

          {/* Comment */}
          <div>
            <label className="mb-1 block text-xs font-extrabold uppercase tracking-wider text-cafe">
              Tu comentario u opinión detallada *
            </label>
            <textarea
              required
              rows={3}
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder="Cuenta qué te pareció la zona, las instalaciones, la seguridad, los servicios y la atención del propietario..."
              className="w-full rounded-2xl border border-border bg-[#FDFBF7] p-3 text-xs font-medium text-cafe outline-none focus:border-forest transition-all resize-none leading-relaxed"
            />
          </div>

          {/* Quick Tags Selector */}
          <div>
            <label className="mb-2 block text-xs font-extrabold uppercase tracking-wider text-cafe">
              Etiquetas destacadas (opcional)
            </label>
            <div className="flex flex-wrap gap-1.5">
              {QUICK_TAGS.map((tag) => {
                const active = selectedTags.includes(tag);
                return (
                  <button
                    key={tag}
                    type="button"
                    onClick={() => handleToggleTag(tag)}
                    className={`px-3 py-1 rounded-full text-[11px] font-bold transition-all ${
                      active
                        ? 'bg-forest text-white shadow-xs'
                        : 'bg-[#FAF5EE] text-cafe hover:bg-forest/10 border border-border-light'
                    }`}
                  >
                    {active ? `✓ ${tag}` : `+ ${tag}`}
                  </button>
                );
              })}
            </div>
          </div>

          <div className="flex items-center justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={() => setShowAddModal(false)}
              className="rounded-xl px-4 py-2.5 text-xs font-bold text-text-muted hover:bg-stone-100"
            >
              Cancelar
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !comment.trim()}
              className="btn-primary !rounded-xl !py-2.5 !px-6 text-xs font-black shadow-md disabled:opacity-50"
            >
              Publicar Opinión
            </button>
          </div>
        </form>
      )}

      {/* Reviews List */}
      <div className="mt-8 space-y-4">
        {reviews.map((rev) => {
          const isLiked = likedReviews[rev.id];
          return (
            <div
              key={rev.id}
              className={`rounded-2xl border p-4 sm:p-5 transition-all ${
                rev.isNew
                  ? 'border-jade/30 bg-jade/5 shadow-sm ring-1 ring-jade/20'
                  : 'border-border-light bg-[#FCFBF8] hover:border-forest/20'
              }`}
            >
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 mb-3">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-br from-forest to-jade text-white font-black text-sm flex items-center justify-center shadow-xs">
                    {rev.userName ? rev.userName.charAt(0).toUpperCase() : 'U'}
                  </div>
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-black text-cafe">
                        {rev.userName}
                      </span>
                      {rev.verifiedTenant && (
                        <span className="inline-flex items-center gap-1 rounded-full bg-dorado/15 px-2 py-0.5 text-[10px] font-black text-[#996515]">
                          <ShieldCheck size={11} /> Inquilino Verificado
                        </span>
                      )}
                      {rev.isNew && (
                        <span className="rounded-full bg-jade/20 px-2 py-0.5 text-[10px] font-black text-jade animate-pulse">
                          Reciente
                        </span>
                      )}
                    </div>
                    <span className="text-[11px] text-text-muted font-medium">
                      {rev.date}
                    </span>
                  </div>
                </div>

                {/* Stars */}
                <div className="flex items-center gap-1 text-dorado">
                  {[1, 2, 3, 4, 5].map((s) => (
                    <Star
                      key={s}
                      size={14}
                      fill={s <= Math.round(rev.rating) ? 'currentColor' : 'none'}
                    />
                  ))}
                  <span className="text-xs font-black text-cafe ml-1">
                    {Number(rev.rating).toFixed(1)}
                  </span>
                </div>
              </div>

              <p className="text-xs sm:text-sm text-text-secondary leading-relaxed font-medium">
                {rev.comment}
              </p>

              {/* Tags */}
              {rev.tags && rev.tags.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-1.5">
                  {rev.tags.map((t) => (
                    <span
                      key={t}
                      className="rounded-lg bg-white px-2.5 py-0.5 text-[10px] font-extrabold text-forest border border-forest/15"
                    >
                      {t}
                    </span>
                  ))}
                </div>
              )}

              {/* Helpful footer */}
              <div className="mt-3 pt-3 border-t border-border-light/60 flex items-center justify-between text-[11px] text-text-muted">
                <span>¿Te resultó útil esta reseña?</span>
                <button
                  type="button"
                  onClick={() => handleLikeReview(rev.id)}
                  className={`flex items-center gap-1.5 px-2.5 py-1 rounded-lg transition-colors ${
                    isLiked
                      ? 'bg-forest text-white font-bold'
                      : 'hover:bg-stone-200/60 text-text-secondary'
                  }`}
                >
                  <ThumbsUp size={12} />
                  <span>{isLiked ? 'Útil (1)' : 'Útil'}</span>
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

import { useState, useEffect, useRef, useMemo } from 'react';
import { createPortal } from 'react-dom';
import {
  Calendar, ChevronLeft, ChevronRight, ChevronDown,
  X, Sparkles
} from 'lucide-react';

const MONTH_NAMES = [
  'Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio',
  'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'
];

const MONTH_SHORT = [
  'Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun',
  'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'
];

const DAY_NAMES = ['Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sá'];

/**
 * Format Date object to YYYY-MM-DD
 */
function toDateString(d) {
  if (!d || isNaN(d.getTime())) return '';
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

/**
 * Parse YYYY-MM-DD to Date object in local time
 */
function parseDateString(str) {
  if (!str) return null;
  const parts = str.split('-');
  if (parts.length !== 3) return null;
  const year = parseInt(parts[0], 10);
  const month = parseInt(parts[1], 10) - 1;
  const day = parseInt(parts[2], 10);
  const d = new Date(year, month, day);
  return isNaN(d.getTime()) ? null : d;
}

/**
 * Format for user display in Spanish
 */
function formatDisplayDate(dateStr) {
  const d = parseDateString(dateStr);
  if (!d) return null;
  const day = d.getDate();
  const month = MONTH_NAMES[d.getMonth()];
  const year = d.getFullYear();
  return `${day} de ${month}, ${year}`;
}

/**
 * RuwaDatePicker — Compact, adaptive date picker with smart centering
 */
export default function RuwaDatePicker({
  value = '',
  onChange = () => {},
  label,
  placeholder = 'dd / mm / aaaa',
  required = false,
  minDate,
  maxDate,
  disabled = false,
  className = '',
  isBirthDate = false,
  id,
}) {
  const [isOpen, setIsOpen] = useState(false);
  const [viewMode, setViewMode] = useState('days'); // 'days' | 'months' | 'years'
  const triggerRef = useRef(null);
  const dropdownRef = useRef(null);
  const [coords, setCoords] = useState({
    top: 0,
    left: 0,
    width: 288,
    isCentered: false,
  });

  // Currently viewed month/year in the calendar
  const initialDate = useMemo(() => {
    const parsed = parseDateString(value);
    if (parsed) return parsed;
    if (isBirthDate) {
      // Default to 25 years ago for birthdate convenience
      const d = new Date();
      d.setFullYear(d.getFullYear() - 25);
      return d;
    }
    return new Date();
  }, [value, isBirthDate]);

  const [viewYear, setViewYear] = useState(initialDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(initialDate.getMonth());
  const [yearGridStart, setYearGridStart] = useState(Math.floor(initialDate.getFullYear() / 12) * 12);

  // Synchronize internal view when value changes
  useEffect(() => {
    const parsed = parseDateString(value);
    if (parsed) {
      setViewYear(parsed.getFullYear());
      setViewMonth(parsed.getMonth());
      setYearGridStart(Math.floor(parsed.getFullYear() / 12) * 12);
    }
  }, [value]);

  // Adaptive positioning: Drops down if fits; otherwise centers in the screen!
  const updateCoords = () => {
    if (!triggerRef.current) return;
    const rect = triggerRef.current.getBoundingClientRect();
    const dropdownWidth = Math.min(290, window.innerWidth - 24);
    // Approximate compact height: presets add ~30px
    const dropdownHeight = isBirthDate ? 300 : 270;
    const spaceBelow = window.innerHeight - rect.bottom;

    // If it does NOT comfortably fit below (with a 16px safety margin),
    // or if the screen height is small (< 680px), center it on the screen!
    const fitsBelow = spaceBelow >= dropdownHeight + 16 && window.innerHeight >= 650;

    if (!fitsBelow) {
      setCoords({
        isCentered: true,
        width: dropdownWidth,
        top: 0,
        left: 0,
      });
      return;
    }

    // Fits cleanly below
    let left = rect.left;
    if (left + dropdownWidth > window.innerWidth - 12) {
      left = Math.max(12, window.innerWidth - dropdownWidth - 12);
    }

    setCoords({
      isCentered: false,
      top: rect.bottom + 6,
      left: Math.max(12, left),
      width: dropdownWidth,
    });
  };

  const handleOpen = () => {
    if (disabled) return;
    updateCoords();
    setIsOpen(true);
    setViewMode('days');
  };

  const handleClose = () => {
    setIsOpen(false);
    setViewMode('days');
  };

  // Close on outside click or escape
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e) => {
      if (e.key === 'Escape') handleClose();
    };

    const handlePointerDown = (e) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(e.target) &&
        triggerRef.current &&
        !triggerRef.current.contains(e.target)
      ) {
        handleClose();
      }
    };

    const handleScrollOrResize = () => {
      updateCoords();
    };

    window.addEventListener('keydown', handleKeyDown);
    document.addEventListener('pointerdown', handlePointerDown);
    window.addEventListener('scroll', handleScrollOrResize, true);
    window.addEventListener('resize', handleScrollOrResize);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.removeEventListener('pointerdown', handlePointerDown);
      window.removeEventListener('scroll', handleScrollOrResize, true);
      window.removeEventListener('resize', handleScrollOrResize);
    };
  }, [isOpen]);

  // Navigation handlers
  const handlePrevMonth = (e) => {
    e.stopPropagation();
    if (viewMonth === 0) {
      setViewMonth(11);
      setViewYear((y) => y - 1);
    } else {
      setViewMonth((m) => m - 1);
    }
  };

  const handleNextMonth = (e) => {
    e.stopPropagation();
    if (viewMonth === 11) {
      setViewMonth(0);
      setViewYear((y) => y + 1);
    } else {
      setViewMonth((m) => m + 1);
    }
  };

  const handlePrevYears = (e) => {
    e.stopPropagation();
    setYearGridStart((y) => y - 12);
  };

  const handleNextYears = (e) => {
    e.stopPropagation();
    setYearGridStart((y) => y + 12);
  };

  // Select day
  const handleSelectDay = (day, isCurrentMonth, e) => {
    e.stopPropagation();
    let targetYear = viewYear;
    let targetMonth = viewMonth;

    if (!isCurrentMonth) {
      if (day > 15) {
        if (viewMonth === 0) {
          targetMonth = 11;
          targetYear -= 1;
        } else {
          targetMonth -= 1;
        }
      } else {
        if (viewMonth === 11) {
          targetMonth = 0;
          targetYear += 1;
        } else {
          targetMonth += 1;
        }
      }
    }

    const selected = new Date(targetYear, targetMonth, day);
    const dateStr = toDateString(selected);

    if (minDate && dateStr < minDate) return;
    if (maxDate && dateStr > maxDate) return;

    onChange(dateStr);
    handleClose();
  };

  const handleSelectMonth = (monthIndex) => {
    setViewMonth(monthIndex);
    setViewMode('days');
  };

  const handleSelectYear = (year) => {
    setViewYear(year);
    setViewMode('months');
  };

  const handleSetToday = (e) => {
    e.stopPropagation();
    const today = new Date();
    const str = toDateString(today);
    if ((!minDate || str >= minDate) && (!maxDate || str <= maxDate)) {
      onChange(str);
      handleClose();
    }
  };

  const handleClear = (e) => {
    e.stopPropagation();
    onChange('');
  };

  // Generate 42 cells for calendar
  const calendarCells = useMemo(() => {
    const firstDayIndex = new Date(viewYear, viewMonth, 1).getDay(); // 0 = Dom
    const daysInCurrentMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
    const daysInPrevMonth = new Date(viewYear, viewMonth, 0).getDate();

    const cells = [];

    // Previous month filler
    for (let i = firstDayIndex - 1; i >= 0; i--) {
      cells.push({
        day: daysInPrevMonth - i,
        isCurrentMonth: false,
      });
    }

    // Current month days
    for (let i = 1; i <= daysInCurrentMonth; i++) {
      cells.push({
        day: i,
        isCurrentMonth: true,
      });
    }

    // Next month filler
    const remaining = 42 - cells.length;
    for (let i = 1; i <= remaining; i++) {
      cells.push({
        day: i,
        isCurrentMonth: false,
      });
    }

    return cells;
  }, [viewYear, viewMonth]);

  const todayStr = toDateString(new Date());
  const selectedDateStr = value;
  const displayLabel = formatDisplayDate(value);

  const birthPresets = [
    { label: '18a', year: new Date().getFullYear() - 18 },
    { label: '25a', year: new Date().getFullYear() - 25 },
    { label: '35a', year: new Date().getFullYear() - 35 },
    { label: '50a', year: new Date().getFullYear() - 50 },
  ];

  // The core calendar content (used both in centered modal and dropdown)
  const calendarContent = (
    <div
      ref={dropdownRef}
      style={{ width: `${coords.width}px` }}
      className="flex flex-col rounded-2xl bg-white border border-[#E8D9C8] shadow-2xl overflow-hidden animate-[scale-up_0.15s_ease-out] select-none"
      onClick={(e) => e.stopPropagation()}
    >
      {/* Top decorative gradient bar */}
      <div className="h-1 w-full bg-gradient-to-r from-forest via-emerald-600 to-dorado" />

      {/* Header bar when centered */}
      {coords.isCentered && (
        <div className="bg-[#FAF5EE] px-3.5 py-2 border-b border-border-light flex items-center justify-between">
          <div className="flex items-center gap-1.5 min-w-0">
            <Calendar size={13} className="text-forest shrink-0" />
            <span className="text-[11px] font-black text-cafe truncate">
              {label || 'Seleccionar fecha'}
            </span>
          </div>
          <button
            type="button"
            onClick={handleClose}
            className="w-5 h-5 rounded-md bg-white border border-border-light flex items-center justify-center text-stone-400 hover:text-cafe transition-colors"
          >
            <X size={11} />
          </button>
        </div>
      )}

      {/* Navigation Header */}
      <div className="bg-[#FAF5EE] px-3 py-1.5 border-b border-border-light flex items-center justify-between">
        {viewMode === 'days' && (
          <>
            <button
              type="button"
              onClick={handlePrevMonth}
              className="w-7 h-7 rounded-lg bg-white border border-border-light flex items-center justify-center text-cafe hover:bg-forest/10 hover:text-forest transition-colors shadow-xs"
              title="Mes anterior"
            >
              <ChevronLeft size={14} />
            </button>

            <div className="flex items-center gap-1">
              <button
                type="button"
                onClick={() => setViewMode('months')}
                className="px-2 py-0.5 rounded-md text-[11px] font-black text-cafe hover:bg-white transition-all flex items-center gap-1"
              >
                {MONTH_NAMES[viewMonth]}
                <ChevronDown size={10} className="text-stone-400" />
              </button>

              <button
                type="button"
                onClick={() => {
                  setYearGridStart(Math.floor(viewYear / 12) * 12);
                  setViewMode('years');
                }}
                className="px-2 py-0.5 rounded-md text-[11px] font-black text-forest bg-forest/10 hover:bg-forest/20 transition-all flex items-center gap-1"
              >
                {viewYear}
                <ChevronDown size={10} className="text-forest" />
              </button>
            </div>

            <button
              type="button"
              onClick={handleNextMonth}
              className="w-7 h-7 rounded-lg bg-white border border-border-light flex items-center justify-center text-cafe hover:bg-forest/10 hover:text-forest transition-colors shadow-xs"
              title="Mes siguiente"
            >
              <ChevronRight size={14} />
            </button>
          </>
        )}

        {viewMode === 'months' && (
          <div className="w-full flex items-center justify-between">
            <span className="text-[11px] font-black text-cafe">Mes ({viewYear})</span>
            <button
              type="button"
              onClick={() => setViewMode('days')}
              className="text-[10px] font-bold text-forest hover:underline"
            >
              Volver
            </button>
          </div>
        )}

        {viewMode === 'years' && (
          <div className="w-full flex items-center justify-between">
            <button
              type="button"
              onClick={handlePrevYears}
              className="w-6 h-6 rounded-md bg-white border border-border-light flex items-center justify-center text-cafe hover:bg-forest/10 hover:text-forest"
            >
              <ChevronLeft size={12} />
            </button>
            <span className="text-[11px] font-black text-cafe">
              {yearGridStart} - {yearGridStart + 11}
            </span>
            <button
              type="button"
              onClick={handleNextYears}
              className="w-6 h-6 rounded-md bg-white border border-border-light flex items-center justify-center text-cafe hover:bg-forest/10 hover:text-forest"
            >
              <ChevronRight size={12} />
            </button>
          </div>
        )}
      </div>

      {/* Age Presets Bar (for birth dates) */}
      {isBirthDate && viewMode === 'days' && (
        <div className="flex items-center justify-between gap-1 px-2.5 py-1 bg-[#FDFBF7] border-b border-border-light/60">
          <span className="text-[9px] font-bold uppercase tracking-wider text-text-muted flex items-center gap-0.5">
            <Sparkles size={10} className="text-dorado" /> Edad:
          </span>
          <div className="flex items-center gap-1">
            {birthPresets.map((preset) => (
              <button
                key={preset.label}
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  setViewYear(preset.year);
                  setYearGridStart(Math.floor(preset.year / 12) * 12);
                }}
                className={`px-1.5 py-0.5 rounded text-[9px] font-black transition-colors ${
                  viewYear === preset.year
                    ? 'bg-dorado text-white'
                    : 'bg-stone-100 text-cafe hover:bg-stone-200'
                }`}
              >
                {preset.label}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Mode: Days Calendar */}
      {viewMode === 'days' && (
        <div className="p-2">
          {/* Days of Week Header */}
          <div className="grid grid-cols-7 gap-0.5 text-center mb-0.5">
            {DAY_NAMES.map((d, i) => (
              <span
                key={d}
                className={`text-[10px] font-extrabold py-0.5 ${
                  i === 0 ? 'text-terracota' : 'text-stone-400'
                }`}
              >
                {d}
              </span>
            ))}
          </div>

          {/* 42 Days Matrix */}
          <div className="grid grid-cols-7 gap-0.5">
            {calendarCells.map((cell, idx) => {
              let cellYear = viewYear;
              let cellMonth = viewMonth;
              if (!cell.isCurrentMonth) {
                if (cell.day > 15) {
                  cellMonth = viewMonth === 0 ? 11 : viewMonth - 1;
                  cellYear = viewMonth === 0 ? viewYear - 1 : viewYear;
                } else {
                  cellMonth = viewMonth === 11 ? 0 : viewMonth + 1;
                  cellYear = viewMonth === 11 ? viewYear + 1 : viewYear;
                }
              }

              const cellDateStr = toDateString(new Date(cellYear, cellMonth, cell.day));
              const isSelected = selectedDateStr === cellDateStr;
              const isToday = todayStr === cellDateStr;
              const isDisabled =
                (minDate && cellDateStr < minDate) ||
                (maxDate && cellDateStr > maxDate);

              return (
                <button
                  key={idx}
                  type="button"
                  disabled={isDisabled}
                  onClick={(e) => handleSelectDay(cell.day, cell.isCurrentMonth, e)}
                  className={`relative h-6.5 sm:h-7 w-full rounded-lg text-[11px] font-bold transition-all flex flex-col items-center justify-center select-none ${
                    isDisabled
                      ? 'opacity-20 cursor-not-allowed text-stone-300'
                      : isSelected
                      ? 'bg-forest text-white font-black shadow-xs z-10'
                      : isToday
                      ? 'border border-dorado text-dorado font-black bg-dorado/5 hover:bg-dorado/15'
                      : cell.isCurrentMonth
                      ? 'text-cafe hover:bg-forest/10 hover:text-forest'
                      : 'text-stone-300 hover:text-stone-500 hover:bg-stone-50'
                  }`}
                >
                  <span>{cell.day}</span>
                  {isToday && !isSelected && (
                    <span className="absolute bottom-0.5 w-1 h-1 rounded-full bg-dorado" />
                  )}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Mode: Months Selector */}
      {viewMode === 'months' && (
        <div className="p-2 grid grid-cols-3 gap-1.5">
          {MONTH_SHORT.map((m, idx) => {
            const isCurrent = viewMonth === idx;
            return (
              <button
                key={m}
                type="button"
                onClick={() => handleSelectMonth(idx)}
                className={`py-2 rounded-lg text-[11px] font-bold transition-all ${
                  isCurrent
                    ? 'bg-forest text-white font-black shadow-xs'
                    : 'bg-[#FDFBF7] text-cafe hover:bg-forest/10 hover:text-forest border border-border-light'
                }`}
              >
                {MONTH_NAMES[idx]}
              </button>
            );
          })}
        </div>
      )}

      {/* Mode: Years Selector */}
      {viewMode === 'years' && (
        <div className="p-2">
          <div className="grid grid-cols-3 gap-1.5">
            {Array.from({ length: 12 }).map((_, i) => {
              const y = yearGridStart + i;
              const isCurrent = viewYear === y;
              return (
                <button
                  key={y}
                  type="button"
                  onClick={() => handleSelectYear(y)}
                  className={`py-2 rounded-lg text-[11px] font-bold transition-all ${
                    isCurrent
                      ? 'bg-forest text-white font-black shadow-xs'
                      : 'bg-[#FDFBF7] text-cafe hover:bg-forest/10 hover:text-forest border border-border-light'
                  }`}
                >
                  {y}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Footer with Quick Shortcuts */}
      <div className="bg-[#FAF5EE] px-3 py-1.5 border-t border-border-light flex items-center justify-between">
        <button
          type="button"
          onClick={handleClear}
          className="text-[10px] font-bold text-text-muted hover:text-terracota transition-colors"
        >
          Limpiar
        </button>

        <div className="flex items-center gap-1.5">
          <button
            type="button"
            onClick={handleSetToday}
            className="px-2 py-0.5 rounded-md bg-white border border-border-light text-[10px] font-black text-forest hover:bg-forest hover:text-white transition-all shadow-xs"
          >
            Hoy
          </button>
          <button
            type="button"
            onClick={handleClose}
            className="px-2.5 py-0.5 rounded-md bg-forest text-[10px] font-black text-white hover:bg-forest-light transition-all shadow-xs"
          >
            Cerrar
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className={`relative ${className}`}>
      {label && (
        <label className="mb-1.5 block text-xs font-extrabold uppercase tracking-wider text-cafe">
          {label} {required && <span className="text-terracota">*</span>}
        </label>
      )}

      {/* Interactive Trigger Field */}
      <div
        ref={triggerRef}
        id={id}
        onClick={handleOpen}
        tabIndex={disabled ? -1 : 0}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            handleOpen();
          }
        }}
        className={`group relative flex items-center justify-between gap-2 rounded-2xl border px-3 py-2 sm:py-2.5 transition-all cursor-pointer select-none ${
          disabled
            ? 'opacity-60 bg-stone-100 border-stone-200 cursor-not-allowed'
            : isOpen
            ? 'border-forest ring-2 ring-forest/15 bg-white shadow-xs'
            : value
            ? 'border-forest/40 bg-[#FDFBF7] hover:border-forest'
            : 'border-[#E8D9C8] bg-[#FDFBF7] hover:border-[#D4962A] hover:bg-white'
        }`}
      >
        <div className="flex items-center gap-2 min-w-0 flex-1">
          <div
            className={`w-6 h-6 rounded-lg flex items-center justify-center transition-colors ${
              value ? 'bg-forest/10 text-forest' : 'bg-stone-100 text-stone-400 group-hover:text-dorado'
            }`}
          >
            <Calendar size={13} />
          </div>

          <div className="min-w-0 flex-1">
            {displayLabel ? (
              <div className="flex items-center gap-1.5">
                <span className="text-xs font-extrabold text-cafe truncate">
                  {displayLabel}
                </span>
                <span className="hidden sm:inline-flex items-center rounded bg-forest/10 px-1.5 py-0.2 text-[9px] font-black text-forest">
                  {value}
                </span>
              </div>
            ) : (
              <span className="text-xs font-semibold text-text-muted">
                {placeholder}
              </span>
            )}
          </div>
        </div>

        <div className="flex items-center gap-1">
          {value && !disabled && (
            <button
              type="button"
              onClick={handleClear}
              title="Borrar fecha"
              className="w-4 h-4 rounded-full flex items-center justify-center text-stone-400 hover:bg-stone-200 hover:text-cafe transition-colors"
            >
              <X size={10} />
            </button>
          )}
          <ChevronDown
            size={14}
            className={`text-stone-400 transition-transform duration-200 ${isOpen ? 'rotate-180 text-forest' : ''}`}
          />
        </div>
      </div>

      {/* Floating Popover or Centered Modal via Portal */}
      {isOpen &&
        createPortal(
          coords.isCentered ? (
            /* Centered on Screen with subtle backdrop when not enough space below */
            <div
              className="fixed inset-0 z-[99999] flex items-center justify-center bg-black/40 backdrop-blur-[1.5px] p-3 animate-[fade-in_0.15s_ease-out]"
              onClick={handleClose}
            >
              {calendarContent}
            </div>
          ) : (
            /* Dropped down right below trigger when space permits */
            <div
              style={{
                position: 'fixed',
                top: `${coords.top}px`,
                left: `${coords.left}px`,
                zIndex: 99999,
              }}
            >
              {calendarContent}
            </div>
          ),
          document.body
        )}
    </div>
  );
}

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useRef,
  useCallback,
} from 'react';
import { useAuth } from './AuthContext';
import { useChat } from './ChatContext';
import { firebaseAuth } from '../lib/firebase';
import {
  ICE_SERVERS,
  CLIENT_WINDOW_ID,
  playIncomingRingTone,
  playCallingRingbackTone,
  playEndCallTone,
  playDtmfTone,
  stopAllTones,
  subscribeToIncomingCalls,
  createCallSession,
  subscribeToCallSession,
  answerCallSession,
  addIceCandidate,
  endCallSession,
  updateCallMuteState,
} from '../lib/callService';

const CallContext = createContext(null);

export function CallProvider({ children }) {
  const { user } = useAuth();
  const { sendMessage } = useChat();

  const chatUserId = String(firebaseAuth?.currentUser?.uid || user?.id || '').trim();
  const chatUserEmail = String(user?.email || firebaseAuth?.currentUser?.email || '').trim().toLowerCase();

  const allUserIds = [
    chatUserId,
    user?.id,
    firebaseAuth?.currentUser?.uid,
    user?._id,
  ].filter(Boolean).map(String);

  const allUserEmails = [
    chatUserEmail,
    user?.email,
    firebaseAuth?.currentUser?.email,
  ].filter(Boolean).map((e) => String(e).trim().toLowerCase());

  const [callStatus, setCallStatus] = useState('idle'); // 'idle' | 'calling' | 'incoming' | 'connected' | 'ended'
  const [activeCall, setActiveCall] = useState(null);
  const [callDuration, setCallDuration] = useState(0);
  const [isMuted, setIsMuted] = useState(false);
  const [isSpeakerOn, setIsSpeakerOn] = useState(true);
  const [isHeld, setIsHeld] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [dialedDigits, setDialedDigits] = useState('');
  const [remoteMuted, setRemoteMuted] = useState(false);
  const [connectionQuality, setConnectionQuality] = useState('good'); // 'good' | 'poor' | 'disconnected'

  const pcRef = useRef(null);
  const localStreamRef = useRef(null);
  const remoteAudioRef = useRef(null);
  const durationTimerRef = useRef(null);
  const unsubCallDocRef = useRef(null);
  const incomingCallUnsubRef = useRef(null);
  const handledCandidatesRef = useRef(new Set());
  const activeCallRef = useRef(null);
  const isSpeakerOnRef = useRef(true);
  const pendingCandidatesRef = useRef([]); // Buffer for ICE candidates before remote desc is set
  const callStatusRef = useRef('idle');
  const isCallerRef = useRef(false);

  // Sync refs with state
  useEffect(() => {
    activeCallRef.current = activeCall;
  }, [activeCall]);

  useEffect(() => {
    isSpeakerOnRef.current = isSpeakerOn;
  }, [isSpeakerOn]);

  useEffect(() => {
    callStatusRef.current = callStatus;
  }, [callStatus]);

  /**
   * Helper: Espera brevemente (máximo maxWaitMs) a que ICE recopile los candidatos locales (host + STUN)
   * para incluirlos directamente en el SDP (Offer o Answer). Esto garantiza que no se pierda ningún candidato
   * local por desfase de tiempo o bloqueadores de peticiones.
   */
  const waitForIceGathering = useCallback((pc, maxWaitMs = 700) => {
    return new Promise((resolve) => {
      if (pc.iceGatheringState === 'complete') {
        resolve();
        return;
      }
      const timer = setTimeout(() => {
        console.log('[CallContext] ICE gathering timeout alcanzado (' + maxWaitMs + 'ms), enviando con candidatos recopilados');
        resolve();
      }, maxWaitMs);

      const checkState = () => {
        console.log('[CallContext] ICE gathering state:', pc.iceGatheringState);
        if (pc.iceGatheringState === 'complete') {
          clearTimeout(timer);
          pc.removeEventListener('icegatheringstatechange', checkState);
          resolve();
        }
      };
      pc.addEventListener('icegatheringstatechange', checkState);
    });
  }, []);

  /**
   * Conecta el stream de audio remoto tanto al elemento DOM como a un objeto Audio en memoria
   * garantizando que la voz suene sin importar si la pestaña está en segundo plano o si el navegador
   * restringe el autoplay.
   */
  const attachRemoteStream = useCallback((stream) => {
    if (!stream) return;

    const audioTracks = stream.getAudioTracks();
    console.log('[CallContext] Conectando audio remoto. Pistas de audio:', audioTracks.length);
    audioTracks.forEach((track) => {
      track.enabled = true;
      console.log(`[CallContext] Pista de audio [${track.id}]: enabled=${track.enabled}, readyState=${track.readyState}, muted=${track.muted}`);
      track.onmute = () => console.log(`[CallContext] Pista ${track.id} esperando paquetes RTP...`);
      track.onunmute = () => console.log(`[CallContext] 🔊 PISTA ${track.id} RECIBIENDO VOZ EN TIEMPO REAL (RTP fluyendo)`);
    });

    const targetVolume = isSpeakerOnRef.current ? 1.0 : 0.4;

    // 1. Elemento del DOM
    const audioEl = remoteAudioRef.current;
    if (audioEl) {
      audioEl.srcObject = stream;
      audioEl.volume = targetVolume;
      audioEl.defaultMuted = false;
      audioEl.muted = false;

      audioEl.play().then(() => {
        console.log('[CallContext] DOM Audio reproduciendo voz exitosamente');
      }).catch((err) => {
        console.warn('[CallContext] DOM Audio bloqueado por política de autoplay, reintentando con clic:', err);
        const retryPlay = () => {
          audioEl.play().catch(() => {});
          window.removeEventListener('click', retryPlay);
        };
        window.addEventListener('click', retryPlay, { once: true });
      });
    }

    // 2. Respaldo directo en memoria (Audio() nativo, inmune a restricciones de DOM y tabs secundarias)
    try {
      if (!window._ruwajayAudio) {
        window._ruwajayAudio = new Audio();
        window._ruwajayAudio.autoplay = true;
      }
      window._ruwajayAudio.srcObject = stream;
      window._ruwajayAudio.volume = targetVolume;
      window._ruwajayAudio.defaultMuted = false;
      window._ruwajayAudio.muted = false;
      window._ruwajayAudio.play().then(() => {
        console.log('[CallContext] Objeto Audio nativo de respaldo reproduciendo correctamente');
      }).catch(() => {});
    } catch (e) {
      console.warn('[CallContext] Error en audio nativo secundario:', e);
    }
  }, []);

  /**
   * Flush any ICE candidates that were buffered before remoteDescription was set.
   */
  const flushPendingCandidates = useCallback(async () => {
    const pc = pcRef.current;
    if (!pc || !pc.remoteDescription) return;

    const pending = [...pendingCandidatesRef.current];
    pendingCandidatesRef.current = [];

    for (const cand of pending) {
      const key = JSON.stringify(cand);
      if (!handledCandidatesRef.current.has(key)) {
        handledCandidatesRef.current.add(key);
        try {
          await pc.addIceCandidate(new RTCIceCandidate(cand));
        } catch (err) {
          console.warn('[CallContext] Error adding buffered ICE candidate:', err);
        }
      }
    }
  }, []);

  /**
   * Process incoming ICE candidates - buffer if no remote desc, add directly otherwise.
   */
  const processRemoteCandidates = useCallback(async (candidates) => {
    const pc = pcRef.current;
    if (!pc || !Array.isArray(candidates) || candidates.length === 0) return;

    for (const cand of candidates) {
      if (!cand || !cand.candidate) continue;
      const key = JSON.stringify(cand);
      if (handledCandidatesRef.current.has(key)) continue;

      if (pc.remoteDescription) {
        handledCandidatesRef.current.add(key);
        try {
          await pc.addIceCandidate(new RTCIceCandidate(cand));
        } catch (err) {
          console.warn('[CallContext] Error adding ICE candidate:', err);
        }
      } else {
        // Buffer until remote description is set
        pendingCandidatesRef.current.push(cand);
      }
    }
  }, []);

  /**
   * Setup WebRTC connection state monitoring.
   */
  const setupConnectionMonitoring = useCallback((pc) => {
    pc.oniceconnectionstatechange = () => {
      const state = pc.iceConnectionState;
      console.log('[CallContext] ICE connection state:', state);

      switch (state) {
        case 'connected':
        case 'completed':
          setConnectionQuality('good');
          break;
        case 'checking':
          setConnectionQuality('good');
          break;
        case 'disconnected':
          setConnectionQuality('poor');
          // Give it a chance to reconnect (ICE restart)
          setTimeout(() => {
            if (pc.iceConnectionState === 'disconnected') {
              setConnectionQuality('disconnected');
            }
          }, 5000);
          break;
        case 'failed':
          setConnectionQuality('disconnected');
          console.warn('[CallContext] ICE connection failed');
          break;
        case 'closed':
          setConnectionQuality('disconnected');
          break;
        default:
          break;
      }
    };

    pc.onconnectionstatechange = () => {
      const state = pc.connectionState;
      console.log('[CallContext] Connection state:', state);

      if (state === 'failed') {
        console.error('[CallContext] Peer connection failed');
        setConnectionQuality('disconnected');
      }
    };
  }, []);

  // Limpiar conexión WebRTC y pistas de audio
  const cleanupMediaAndPeer = useCallback(() => {
    stopAllTones();

    if (durationTimerRef.current) {
      clearInterval(durationTimerRef.current);
      durationTimerRef.current = null;
    }

    if (unsubCallDocRef.current) {
      unsubCallDocRef.current();
      unsubCallDocRef.current = null;
    }

    if (incomingCallUnsubRef.current) {
      incomingCallUnsubRef.current();
      incomingCallUnsubRef.current = null;
    }

    if (localStreamRef.current) {
      localStreamRef.current.getTracks().forEach((track) => track.stop());
      localStreamRef.current = null;
    }

    if (pcRef.current) {
      try {
        pcRef.current.ontrack = null;
        pcRef.current.onicecandidate = null;
        pcRef.current.oniceconnectionstatechange = null;
        pcRef.current.onconnectionstatechange = null;
        pcRef.current.close();
      } catch { /* ignore */ }
      pcRef.current = null;
    }

    if (remoteAudioRef.current) {
      remoteAudioRef.current.pause();
      remoteAudioRef.current.srcObject = null;
    }

    if (window._ruwajayAudio) {
      try {
        window._ruwajayAudio.pause();
        window._ruwajayAudio.srcObject = null;
      } catch {}
    }

    handledCandidatesRef.current.clear();
    pendingCandidatesRef.current = [];
    setIsMuted(false);
    setIsHeld(false);
    setDialedDigits('');
    setIsMinimized(false);
    setRemoteMuted(false);
    setConnectionQuality('good');
  }, []);

  // Escuchar llamadas entrantes dirigidas a este usuario en segundo plano (Firestore + Local)
  useEffect(() => {
    return subscribeToIncomingCalls({
      userIds: allUserIds,
      userEmails: allUserEmails,
      userName: user?.name || '',
    }, (incomingData) => {
      // Ignorar únicamente si esta ventana ya está activamente en llamada (calling o connected)
      if (activeCallRef.current && (activeCallRef.current.status === 'calling' || activeCallRef.current.status === 'connected')) {
        return;
      }
      if (incomingData.callerWindowId && incomingData.callerWindowId === CLIENT_WINDOW_ID) return;

      setActiveCall({
        ...incomingData,
        isCaller: false, // La persona que recibe NO es el emisor
      });
      setCallStatus('incoming');
      playIncomingRingTone();

      // Escuchar si la otra parte cancela o cuelga mientras aún está sonando
      if (incomingCallUnsubRef.current) {
        incomingCallUnsubRef.current();
      }
      incomingCallUnsubRef.current = subscribeToCallSession(incomingData.id, (callUpdate) => {
        if (callUpdate && (callUpdate.status === 'ended' || callUpdate.status === 'rejected')) {
          if (incomingCallUnsubRef.current) {
            incomingCallUnsubRef.current();
            incomingCallUnsubRef.current = null;
          }
          cleanupMediaAndPeer();
          setActiveCall(null);
          setCallStatus('idle');
        }
      }, incomingData.roomId);

      // Alerta visual parpadeante en la pestaña del navegador
      try {
        const origTitle = document.title;
        document.title = '📞 ¡LLAMADA ENTRANTE! - RuwaJay';
        const interval = setInterval(() => {
          document.title = document.title.includes('LLAMADA') ? origTitle : '📞 ¡LLAMADA ENTRANTE! - RuwaJay';
        }, 1100);

        const stopTitleAlert = () => {
          clearInterval(interval);
          document.title = origTitle;
          window.removeEventListener('focus', stopTitleAlert);
        };
        window.addEventListener('focus', stopTitleAlert);
      } catch { /* ignore */ }

      // Notificación del sistema si está habilitada
      if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
        try {
          new Notification('📞 Llamada entrante en RuwaJay', {
            body: `${incomingData.callerName || 'Contacto'} te está llamando...`,
            icon: incomingData.callerAvatar || `${import.meta.env.BASE_URL}Casas/cat-familiar.jpg`,
            tag: 'ruwajay-call-ring',
          });
        } catch { /* ignore */ }
      }
    });
  }, [allUserIds.join(','), allUserEmails.join(','), user?.name, cleanupMediaAndPeer]);

  // Formato mm:ss para el resumen en el chat
  const formatDurationString = (sec) => {
    const m = Math.floor(sec / 60);
    const s = sec % 60;
    return `${m}:${s < 10 ? '0' : ''}${s}`;
  };

  // INICIAR LLAMADA (Cliente -> Propietario o Propietario -> Cliente)
  const startCall = useCallback(async ({
    recipientId,
    recipientName,
    recipientAvatar = '',
    recipientPhone = '',
    recipientEmail = '',
    propertyTitle = 'Propiedad RuwaJay',
    propertyImage = '',
    roomId = null,
    conversation = null,
  }) => {
    if (!recipientId && !recipientEmail && !recipientName) {
      window.alert('No se pudo identificar al contacto para iniciar la llamada.');
      return;
    }

    cleanupMediaAndPeer();
    isCallerRef.current = true;

    try {
      // 1. Obtener micrófono del usuario
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      localStreamRef.current = stream;

      // 2. Crear conexión PeerConnection
      const pc = new RTCPeerConnection(ICE_SERVERS);
      pcRef.current = pc;

      // Setup connection monitoring
      setupConnectionMonitoring(pc);

      // Agregar pistas locales
      stream.getTracks().forEach((track) => pc.addTrack(track, stream));

      // Escuchar pista remota de audio - CRITICAL: must handle ontrack
      pc.ontrack = (event) => {
        console.log('[CallContext] Caller received remote track:', event.track.kind);
        if (event.streams && event.streams[0]) {
          attachRemoteStream(event.streams[0]);
        } else if (event.track) {
          // Fallback: create stream from track
          const remoteStream = new MediaStream([event.track]);
          attachRemoteStream(remoteStream);
        }
      };

      // Buffer para candidatos que se generen antes de tener el ID de sesión
      let createdSessionId = null;
      const bufferedEarlyCandidates = [];

      // 3. REGISTRAR onicecandidate ANTES de setLocalDescription para no perder ningún candidato host
      pc.onicecandidate = (event) => {
        if (event.candidate) {
          console.log('[CallContext] Llamante generó candidato ICE:', event.candidate.candidate?.slice(0, 45));
          if (createdSessionId) {
            addIceCandidate(createdSessionId, event.candidate, true, roomId || conversation?.id || null);
          } else {
            bufferedEarlyCandidates.push(event.candidate);
          }
        }
      };

      // 4. Crear SDP Offer
      const offer = await pc.createOffer({ offerToReceiveAudio: true });
      await pc.setLocalDescription(offer);

      // Esperar brevemente a que se recopilen los candidatos locales y se incluyan en el SDP
      await waitForIceGathering(pc, 700);

      playCallingRingbackTone();

      // Recopilar todos los posibles emails e IDs para matching sin fallos
      const allRecipientEmails = [
        recipientEmail,
        conversation?.ownerEmail,
        conversation?.seekerEmail,
        conversation?.participantEmail,
      ].filter(Boolean).map((e) => String(e).toLowerCase().trim());

      const allRecipientIds = [
        recipientId,
        conversation?.ownerId,
        conversation?.seekerId,
        conversation?.participantId,
      ].filter(Boolean).map(String);

      // 5. Registrar sesión de llamada con el SDP completo (que ya incluye candidatos host)
      const callData = {
        callerId: chatUserId,
        callerIds: allUserIds,
        callerName: user?.name || 'Cliente',
        callerAvatar: user?.avatarImage || user?.photoURL || user?.avatar || '',
        callerEmail: chatUserEmail,
        callerEmails: allUserEmails,
        receiverId: recipientId,
        receiverIds: allRecipientIds,
        receiverName: recipientName || 'Propietario',
        receiverAvatar: recipientAvatar,
        receiverPhone: recipientPhone,
        receiverEmail: recipientEmail,
        receiverEmails: allRecipientEmails,
        ownerId: conversation?.ownerId || (recipientId !== chatUserId ? recipientId : null),
        seekerId: conversation?.seekerId || chatUserId,
        ownerEmail: conversation?.ownerEmail || (recipientEmail !== chatUserEmail ? recipientEmail : null),
        seekerEmail: conversation?.seekerEmail || chatUserEmail,
        participantEmails: [
          ...allUserEmails,
          ...allRecipientEmails,
        ].filter(Boolean),
        participants: [
          ...allUserIds,
          ...allRecipientIds,
        ].filter(Boolean),
        propertyTitle,
        propertyImage,
        roomId: roomId || conversation?.id || null,
        callerWindowId: CLIENT_WINDOW_ID,
        isCaller: true,
        offer: { sdp: pc.localDescription?.sdp || offer.sdp, type: pc.localDescription?.type || offer.type },
        callerMuted: false,
        receiverMuted: false,
      };

      const session = await createCallSession(callData);
      createdSessionId = session.id;
      setActiveCall({ ...callData, id: session.id });
      setCallStatus('calling');
      setCallDuration(0);

      // Despachar cualquier candidato que se haya generado mientras se guardaba la sesión
      for (const cand of bufferedEarlyCandidates) {
        addIceCandidate(session.id, cand, true, callData.roomId);
      }

      // 6. Escuchar la respuesta del receptor
      unsubCallDocRef.current = subscribeToCallSession(session.id, async (updatedData) => {
        if (!updatedData) return;

        // Track remote mute state
        if (updatedData.receiverMuted !== undefined) {
          setRemoteMuted(updatedData.receiverMuted);
        }

        // Si el receptor contestó
        if (updatedData.status === 'connected' && updatedData.answer) {
          stopAllTones();
          setCallStatus('connected');

          if (!pc.currentRemoteDescription && updatedData.answer?.sdp) {
            try {
              await pc.setRemoteDescription(new RTCSessionDescription(updatedData.answer));
              console.log('[CallContext] Caller: Remote description set, flushing candidates');
              // Flush any buffered candidates now that remote desc is set
              await flushPendingCandidates();
            } catch (err) {
              console.warn('Error aplicando SDP Answer:', err);
            }
          }

          // Iniciar contador de duración
          if (!durationTimerRef.current) {
            durationTimerRef.current = setInterval(() => {
              setCallDuration((prev) => prev + 1);
            }, 1000);
          }
        }

        // Incorporar candidatos ICE del receptor
        if (Array.isArray(updatedData.receiverCandidates)) {
          await processRemoteCandidates(updatedData.receiverCandidates);
        }

        // Si la llamada fue rechazada o finalizada por la otra parte
        if (updatedData.status === 'ended' || updatedData.status === 'rejected') {
          playEndCallTone();
          setCallStatus('ended');
          setTimeout(() => {
            cleanupMediaAndPeer();
            setActiveCall(null);
            setCallStatus('idle');
          }, 1500);
        }
      });
    } catch (err) {
      console.warn('Error al iniciar llamada WebRTC:', err);
      stopAllTones();
      cleanupMediaAndPeer();
      window.alert('No se pudo acceder al micrófono para la llamada. Por favor permite el acceso al micrófono en tu navegador.');
    }
  }, [chatUserId, chatUserEmail, allUserIds, allUserEmails, user, cleanupMediaAndPeer, attachRemoteStream, setupConnectionMonitoring, flushPendingCandidates, processRemoteCandidates]);

  // ACEPTAR LLAMADA ENTRANTE (Receptor)
  const acceptCall = useCallback(async () => {
    if (!activeCall?.id || !activeCall?.offer) return;
    stopAllTones();
    isCallerRef.current = false;

    try {
      // 1. Micrófono del receptor
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
        },
      });
      localStreamRef.current = stream;

      // 2. PeerConnection
      const pc = new RTCPeerConnection(ICE_SERVERS);
      pcRef.current = pc;

      // Setup connection monitoring
      setupConnectionMonitoring(pc);

      stream.getTracks().forEach((track) => pc.addTrack(track, stream));

      // Listen for remote audio track - CRITICAL
      pc.ontrack = (event) => {
        console.log('[CallContext] Receiver got remote track:', event.track.kind);
        if (event.streams && event.streams[0]) {
          attachRemoteStream(event.streams[0]);
        } else if (event.track) {
          const remoteStream = new MediaStream([event.track]);
          attachRemoteStream(remoteStream);
        }
      };

      // 3. Aplicar Offer del llamante
      await pc.setRemoteDescription(new RTCSessionDescription(activeCall.offer));
      console.log('[CallContext] Receiver: Remote description (offer) set');

      // Agregar candidatos ICE del llamante que ya llegaron
      if (Array.isArray(activeCall.callerCandidates)) {
        for (const cand of activeCall.callerCandidates) {
          if (!cand || !cand.candidate) continue;
          const key = JSON.stringify(cand);
          if (!handledCandidatesRef.current.has(key)) {
            handledCandidatesRef.current.add(key);
            try {
              await pc.addIceCandidate(new RTCIceCandidate(cand));
            } catch (err) {
              console.warn('[CallContext] Error adding caller candidate:', err);
            }
          }
        }
      }

      // REGISTRAR onicecandidate ANTES de setLocalDescription en el receptor
      pc.onicecandidate = (event) => {
        if (event.candidate) {
          console.log('[CallContext] Receptor generó candidato ICE:', event.candidate.candidate?.slice(0, 45));
          addIceCandidate(activeCall.id, event.candidate, false, activeCall.roomId);
        }
      };

      // 4. Crear Answer
      const answer = await pc.createAnswer();
      await pc.setLocalDescription(answer);

      // Esperar brevemente a recopilar candidatos host del receptor
      await waitForIceGathering(pc, 700);

      // 5. Enviar Answer al llamante con el SDP completo
      const finalAnswerSdp = pc.localDescription?.sdp || answer.sdp;
      await answerCallSession(activeCall.id, { sdp: finalAnswerSdp, type: answer.type }, activeCall.roomId);

      setCallStatus('connected');
      setCallDuration(0);

      // Iniciar cronómetro
      durationTimerRef.current = setInterval(() => {
        setCallDuration((prev) => prev + 1);
      }, 1000);

      // 6. Escuchar actualizaciones (fin de llamada + candidatos adicionales + mute state)
      unsubCallDocRef.current = subscribeToCallSession(activeCall.id, async (updatedData) => {
        if (!updatedData) return;

        // Track remote mute state (caller's mute state)
        if (updatedData.callerMuted !== undefined) {
          setRemoteMuted(updatedData.callerMuted);
        }

        // Incorporar candidatos ICE adicionales del llamante
        if (Array.isArray(updatedData.callerCandidates)) {
          await processRemoteCandidates(updatedData.callerCandidates);
        }

        if (updatedData.status === 'ended' || updatedData.status === 'rejected') {
          playEndCallTone();
          setCallStatus('ended');
          setTimeout(() => {
            cleanupMediaAndPeer();
            setActiveCall(null);
            setCallStatus('idle');
          }, 1500);
        }
      });
    } catch (err) {
      console.warn('Error contestando llamada:', err);
      cleanupMediaAndPeer();
      window.alert('No se pudo acceder al micrófono para contestar la llamada.');
    }
  }, [activeCall, cleanupMediaAndPeer, attachRemoteStream, setupConnectionMonitoring, processRemoteCandidates]);

  // RECHAZAR LLAMADA
  const rejectCall = useCallback(async () => {
    stopAllTones();
    const callToReject = activeCall;
    setCallStatus('ended');

    if (callToReject?.id) {
      await endCallSession(callToReject.id, 'rejected', callToReject.roomId);
      if (callToReject.roomId) {
        sendMessage(callToReject.roomId, '📞 Llamada rechazada');
      }
    }

    cleanupMediaAndPeer();
    setActiveCall(null);
    setCallStatus('idle');
  }, [activeCall, cleanupMediaAndPeer, sendMessage]);

  // FINALIZAR / COLGAR LLAMADA ACTIVA
  const endCall = useCallback(async () => {
    playEndCallTone();
    const currentCallSnapshot = activeCall;
    const finalDuration = callDuration;

    setCallStatus('ended');

    if (currentCallSnapshot?.id) {
      await endCallSession(currentCallSnapshot.id, 'ended', currentCallSnapshot.roomId);
      if (currentCallSnapshot.roomId) {
        const durText = finalDuration > 0 ? ` (${formatDurationString(finalDuration)})` : '';
        sendMessage(currentCallSnapshot.roomId, `📞 Llamada de voz finalizada${durText}`);
      }
    }

    setTimeout(() => {
      cleanupMediaAndPeer();
      setActiveCall(null);
      setCallStatus('idle');
      setCallDuration(0);
    }, 1200);
  }, [activeCall, callDuration, cleanupMediaAndPeer, sendMessage]);

  // Silenciar / Activar micrófono + notify the other party via Firestore
  const toggleMute = useCallback(() => {
    if (localStreamRef.current) {
      const audioTrack = localStreamRef.current.getAudioTracks()[0];
      if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        const newMuted = !audioTrack.enabled;
        setIsMuted(newMuted);

        // Notify the other party of mute state via Firestore
        const currentCall = activeCallRef.current;
        if (currentCall?.id) {
          updateCallMuteState(
            currentCall.id,
            isCallerRef.current,
            newMuted,
            currentCall.roomId
          );
        }
      }
    }
  }, []);

  // Altavoz: Alterna entre altavoz al 100% y modo auricular/discreto al 40%
  const toggleSpeaker = useCallback(() => {
    setIsSpeakerOn((prev) => {
      const next = !prev;
      if (remoteAudioRef.current) {
        remoteAudioRef.current.volume = next ? 1.0 : 0.4;
      }
      return next;
    });
  }, []);

  // Poner llamada en espera (Hold)
  const toggleHold = useCallback(() => {
    setIsHeld((prev) => {
      const next = !prev;
      if (localStreamRef.current) {
        localStreamRef.current.getAudioTracks().forEach((track) => {
          track.enabled = !next && !isMuted;
        });
      }
      return next;
    });
  }, [isMuted]);

  // Minimizar a widget flotante / Expandir modal completo
  const toggleMinimize = useCallback(() => {
    setIsMinimized((prev) => !prev);
  }, []);

  // Marcar número en teclado DTMF
  const sendDtmfTone = useCallback((digit) => {
    setDialedDigits((prev) => (prev + digit).slice(-18));
    playDtmfTone(digit);
  }, []);

  // Borrar dígitos marcados
  const clearDialedDigits = useCallback(() => {
    setDialedDigits('');
  }, []);

  const value = {
    callStatus,
    activeCall,
    callDuration,
    isMuted,
    isSpeakerOn,
    isHeld,
    isMinimized,
    dialedDigits,
    remoteMuted,
    connectionQuality,
    remoteAudioRef,
    startCall,
    acceptCall,
    rejectCall,
    endCall,
    toggleMute,
    toggleSpeaker,
    toggleHold,
    toggleMinimize,
    sendDtmfTone,
    clearDialedDigits,
  };

  return (
    <CallContext.Provider value={value}>
      {children}
      {/* Elemento de audio global invisible pero presente en el DOM layout (no display:none para evitar throttle de Chromium) */}
      <audio
        ref={remoteAudioRef}
        autoPlay
        playsInline
        style={{
          position: 'fixed',
          top: '-9999px',
          left: '-9999px',
          width: '1px',
          height: '1px',
          opacity: 0.01,
          pointerEvents: 'none',
        }}
      />
    </CallContext.Provider>
  );
}

export function useCall() {
  const context = useContext(CallContext);
  if (!context) {
    throw new Error('useCall debe usarse dentro de CallProvider');
  }
  return context;
}

import { createContext, useContext, useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from './AuthContext';
import { deleteDoc, doc, onSnapshot, collection, setDoc, serverTimestamp } from 'firebase/firestore';
import { firestore } from '../lib/firebase';

const FavoritesContext = createContext(null);
export function FavoritesProvider({ children }) {
  const { user } = useAuth();
  const uid = user?.id || null;
  const activeUid = useRef(uid);
  activeUid.current = uid;
  const [favoriteState, setFavoriteState] = useState({ uid: null, items: [] });
  const [searchState, setSearchState] = useState({ uid: null, items: [] });
  const favorites = favoriteState.uid === uid ? favoriteState.items : [];
  const recentSearches = searchState.uid === uid ? searchState.items : [];

  useEffect(() => {
    let active = true;
    setFavoriteState({ uid, items: [] });
    // Discard the previous unscoped cache. Firestore owns favorites.
    try {
      localStorage.removeItem('ruwajay_favorites');
      localStorage.removeItem('ruwajay_recent_searches');
      const saved = uid ? JSON.parse(localStorage.getItem('ruwajay_recent_searches:' + uid) || '[]') : [];
      setSearchState({ uid, items: Array.isArray(saved) ? saved.slice(0, 10) : [] });
    } catch { setSearchState({ uid, items: [] }); }
    if (!uid || !firestore) return () => { active = false; };
    const unsubscribe = onSnapshot(collection(firestore, 'users', uid, 'favorites'), snapshot => {
      if (active && activeUid.current === uid) setFavoriteState({ uid, items: snapshot.docs.map(d => d.id) });
    }, error => {
      if (active && activeUid.current === uid) setFavoriteState({ uid, items: [] });
      console.error('No se pudieron cargar los favoritos:', error);
    });
    return () => { active = false; unsubscribe(); };
  }, [uid]);

  useEffect(() => {
    if (uid && searchState.uid === uid) {
      try { localStorage.setItem('ruwajay_recent_searches:' + uid, JSON.stringify(searchState.items)); } catch { /* Storage may be disabled. */ }
    }
  }, [uid, searchState]);

  const toggleFavorite = useCallback(async propertyId => {
    if (!uid || !firestore) return;
    const id = String(propertyId);
    const removing = favorites.includes(id);
    setFavoriteState(prev => ({ uid, items: removing
      ? (prev.uid === uid ? prev.items : []).filter(value => value !== id)
      : [...new Set([...(prev.uid === uid ? prev.items : []), id])] }));
    try {
      const target = doc(firestore, 'users', uid, 'favorites', id);
      if (removing) await deleteDoc(target);
      else await setDoc(target, { propertyId: id, createdAt: serverTimestamp() });
    } catch {
      if (activeUid.current !== uid) return;
      setFavoriteState(prev => prev.uid !== uid ? prev : ({ uid, items: removing
        ? [...new Set([...prev.items, id])] : prev.items.filter(value => value !== id) }));
      window.alert('No se pudo guardar el favorito. Revisa tu conexión.');
    }
  }, [uid, favorites]);
  const isFavorite = useCallback(id => favorites.includes(String(id)), [favorites]);
  const addRecentSearch = useCallback(search => {
    if (!uid) return;
    setSearchState(prev => ({ uid, items: [search, ...(prev.uid === uid ? prev.items : []).filter(s => s.query !== search.query)].slice(0, 10) }));
  }, [uid]);
  const clearRecentSearches = useCallback(() => setSearchState({ uid, items: [] }), [uid]);
  return <FavoritesContext.Provider value={{ favorites, toggleFavorite, isFavorite, recentSearches, addRecentSearch, clearRecentSearches }}>{children}</FavoritesContext.Provider>;
}
export function useFavorites() {
  const context = useContext(FavoritesContext);
  if (!context) throw new Error('useFavorites must be used within FavoritesProvider');
  return context;
}

