          {/* View toggle */}
          <div className="flex flex-1 items-center overflow-hidden rounded-xl border border-border bg-white sm:flex-none">
            <button
              onClick={() => setSearchParams({ ...Object.fromEntries(searchParams), view: 'list' })}
