                    <button
                      key={key}
                      onClick={() => setFilters({ ...filters, [key]: !filters[key] })}
                      className={`flex min-h-11 items-center gap-1.5 rounded-full px-3.5 py-1.5 text-xs font-bold transition-all ${
                        filters[key]
                          ? 'bg-forest text-white shadow-xs'
